/* 第二十章 · 沓中屯田 — 1:1 演出流，逆向自 R_20.eex */
(function(){
 if(!window.JW_CHAPTERS) window.JW_CHAPTERS=[];
 window.JW_CHAPTERS.push({"id":"ch20","num":20,"title":"第二十章 · 沓中屯田","desc":"第二十章 · 沓中屯田（原版剧本 R_20.eex 完整演出流）","intro":{"title":"第二十章 · 沓中屯田","script":[{"op":"clear_flags","args":[]},{"op":"chapter_title","args":[2,"九伐中原"]},{"op":"play_sound","args":[0]},{"op":"change_scene","args":[2,65535,65535,50,65535]},{"op":"actor_appear","args":[49,52,77,0,0]},{"op":"actor_appear","args":[50,59,73,0,0]},{"op":"actor_appear","args":[205,49,56,2,0]},{"op":"actor_appear","args":[0,55,56,2,0]},{"op":"actor_appear","args":[257,39,61,1,0]},{"op":"actor_appear","args":[40,65,61,3,0]},{"op":"actor_appear","args":[53,65,56,3,0]},{"op":"actor_appear","args":[55,39,56,1,0]},{"op":"actor_appear","args":[51,39,51,1,0]},{"op":"actor_appear","args":[47,39,46,1,0]},{"op":"actor_appear","args":[652,65,51,3,0]},{"op":"actor_appear","args":[155,65,46,3,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["降将郭循"]},{"op":"place_name","args":["成都 皇宫"]},{"op":"dialog","args":["&刘禅\n这位就是卫将军这次俘获的敌将？\n&郭循\n………"]},{"op":"actor_action","args":[40,2]},{"op":"dialog","args":["&诸葛瞻\n好大胆子，圣上在问你话！\n&刘禅\n无妨，这样壮烈的好汉，如果能为我大汉\n所用的话不知道有多好。"]},{"op":"actor_action","args":[40,0]},{"op":"delay","args":[5]},{"op":"actor_action","args":[205,6]},{"op":"dialog","args":["&郭循\n我愿意投降……"]},{"op":"actor_face","args":[0,0,3]},{"op":"dialog","args":["&姜维\n咦？\n&樊建\n怎么这么干脆？\n&郤正\n（感觉这一切大有问题，但是又说不出\n到底是什么样的问题。）"]},{"op":"delay","args":[5]},{"op":"actor_move","args":[0,205,0,49,58,2]},{"op":"actor_action","args":[205,0]},{"op":"actor_face","args":[0,0,2]},{"op":"delay","args":[5]},{"op":"actor_appear","args":[58,52,8,2,0]},{"op":"actor_move","args":[0,58,0,52,63,2]},{"op":"actor_action","args":[58,0]},{"op":"actor_face","args":[58,2,0]},{"op":"dialog","args":["&关统\n你想做什么？若敢轻举妄动，我关统绝对\n要你人头落地。\n&刘禅\n虎贲中郎将，没有关系的，朕认为他只是\n要上来谢恩而已。"]},{"op":"actor_action","args":[58,0]},{"op":"delay","args":[5]},{"op":"actor_face","args":[51,6,2]},{"op":"dialog","args":["&陈祗\n陛下，既然这位郭将军愿意弃暗投明，\n那么待遇也该比照之前两位有同样经历\n的将军才是。\n&陈祗\n如此一来，“反魏义士”的名号才可以\n响亮，进而吸引更多人来投奔。\n&刘禅\n说得好，那么刚好左将军这个职位出缺，\n就让郭循来担任好了。\n&郭循\n（机会，我要等机会来做我唯一可以做的\n事情。）\n&姜维\n（郭循刚才似乎想要靠近圣上，莫非他想\n要藉著这机会行刺？）\n&陈祗\n（来吧，这个不安定要素已经投下了，\n就看事情什么时候爆发。）"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[39]},{"op":"change_scene","args":[2,65535,65535,73,65535]},{"op":"actor_appear","args":[651,35,49,1,0]},{"op":"actor_appear","args":[12,43,49,3,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["伯苗故去"]},{"op":"place_name","args":["河边"]},{"op":"dialog","args":["&邓芝\n根据礼法，人年纪过了六十就不该带兵，\n为什么你现在还在带兵？"]},{"op":"actor_action","args":[12,2]},{"op":"dialog","args":["&宗预\n笑话，你七十岁还领兵，我才六十岁，\n怎么不可以接受兵权？\n&邓芝\n说得也是…这几年你变得越来越伶牙俐齿\n了。"]},{"op":"actor_action","args":[12,0]},{"op":"dialog","args":["&宗预\n你今天为什么找我？\n&邓芝\n你知道两年前我去攻打涪陵蛮族的时候，\n刚好又看见有只母猴子在那跳来跳去，一\n时不高兴就射它。\n&宗预\n（七十岁了还像十七岁的小孩一样射猴子\n，实在有够无聊。）\n&邓芝\n结果没想到一旁的小猴子居然会帮母猴子\n拔出箭来，而且还用树叶塞住创伤。\n&宗预\n我不懂，那不就表示小猴子很聪明？\n&邓芝\n你真是蠢！那表示我违反物种的天性，\n距离死期已经不远了。\n&宗预\n这什么鬼话？一点根据都没有。\n&邓芝\n但是当范长生那样的高人也在旁边说的\n时候，你说我该不该相信呢？\n&宗预\n你见到范长生了？\n&邓芝\n是呀…他真的是个高人，所以他说的话\n我当然没有道理不信。\n&邓芝\n只是比起我的生死，他的预言更让我觉得\n惊悚…他说大汉政权在这十几年内会有个\n重大考验，如果无法通过就会灭亡。\n&邓芝\n你说我是该信还是不该信？\n&宗预\n说实话，我也不知道。现在国政虽然由\n文伟撑著，伯约也负责国防事务，但是\n和贼营的实力差距还是很大。\n&邓芝\n从上次兴势一战后也过了快八年，贼营\n又发生几次政变所以无暇入侵。\n&邓芝\n然而等到贼营政权开始稳定之后，入侵\n我大汉是必然发生的事情。\n&邓芝\n所以我希望你能代替我去帮忙伯约，至少\n能够分担他一些辛劳，否则我怕到时候没\n有人来应付那样的变局。\n&宗预\n不用你说我也有这个打算…\n&邓芝\n这样我也可以安心了。\n&宗预\n伯苗，你也不要这样就放弃希望，那个\n范长生说的话也不过是大略的预言。\n&邓芝\n当子均和德信都故去的时候，我也早该有\n不能独活的觉悟。\n&邓芝\n其实我这样走了还是落得轻松，而你却得\n继续和大家一起支撑这危险的政局。\n&宗预\n我并没有这样的感觉。\n&邓芝\n是吗？那么一切的事情都拜托你了。"]},{"op":"delay","args":[5]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[39]},{"op":"change_scene","args":[1,30,0,65535,65535]},{"op":"change_scene","args":[0,9,65535,65535,65535]},{"op":"fade_out","args":[]},{"op":"caption","args":["公元二五一年，蜀汉车骑将军邓芝去世，其担任将军二十多年，赏罚明断，",1,0,1]},{"op":"caption","args":["，体恤士卒。身上衣食从官府资取，不治私有财产，妻子甚至有饥寒的日子。",1,1,1]},{"op":"delay","args":[5]},{"op":"caption","args":["三国志评曰：“邓芝在东，马忠在南，王平在北境，咸著名迹。”",0,0,1]},{"op":"caption","args":["在这三位蜀汉都督都过世之后，蜀汉政局又有新的转变。",1,1,1]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[63]},{"op":"change_scene","args":[2,65535,65535,25,65535]},{"op":"actor_appear","args":[93,64,60,2,0]},{"op":"actor_appear","args":[94,60,65,0,0]},{"op":"actor_appear","args":[130,66,65,0,0]},{"op":"fade_out","args":[]},{"op":"delay","args":[3]},{"op":"title_text","args":["寿春之叛"]},{"op":"place_name","args":["洛阳司马家"]},{"op":"delay","args":[5]},{"op":"actor_action","args":[94,6]},{"op":"dialog","args":["&司马师\n爹，刚才接到公休（诸葛诞）十万火急\n的来信。\n&司马懿\n嗯…\n&司马昭\n难道爹不想知道发生什么事？\n&司马懿\n不用看老夫也知道，寿春的太尉王凌图谋\n造反，不信你们打开来看看。"]},{"op":"actor_action","args":[94,0]},{"op":"dialog","args":["&司马师\n真的如爹所说，王凌意图拥立楚王曹彪来\n推翻我们司马家。\n&司马懿\n真是危险，若不是老夫早安插公休在那边\n，今天淮南那边可能会发生大规模兵变。\n&司马师\n爹您明明知道王凌根本就是曹爽的余党，\n为什么还是让他率领重兵在那个地方？\n&司马懿\n扫掉一个王凌，还有好几个麻烦人物，\n例如说豫州的毌丘俭，你是要老夫刺激\n那些人一起造反？\n&司马昭\n我明白了，爹是想要一个个慢慢把他们\n给拔掉。\n&司马懿\n只对一半，老夫还要用这个机会一口气把\n曹家的亲族也给解决。\n&司马懿\n王凌这个蠢蛋想出拥立新帝这招，却没\n想到老夫等这一刻很久了。\n&司马懿\n这下所有的曹氏亲族都可以安上谋反的\n罪名，参与者处死，其他人也可以圈禁\n起来。\n&司马师\n爹，您的目标其实是东乡公主对吧。\n&司马懿\n不错不错，我的师儿可是越来越有长进\n，这次换老夫把她赶出中央，哈哈哈…\n&司马懿\n只是光有公休的密函还是不够，因为老夫\n不想要让他的立场曝光。"]},{"op":"actor_action","args":[93,17]},{"op":"dialog","args":["&司马懿\n师儿，去通知公休要他尽量拖延王凌叛变\n的时间。\n&司马懿\n昭儿，现在派人去严密监视荆豫一带的都\n督或是刺史，我想王凌在得不到公休积极\n参与谋反的表示后，一定会另外找帮手。\n&司马懿\n到时候他胡乱找对象，一定会找到一些\n胆小怕事的人参与。\n&司马师\n爹难道已经猜到他会找谁？"]},{"op":"actor_action","args":[93,3]},{"op":"dialog","args":["&司马懿\n兖州刺史令狐愚刚死，他的继任人黄华\n是个无可救药的胆小鬼…呵呵呵…"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[30]},{"op":"change_scene","args":[2,65535,65535,12,65535]},{"op":"actor_appear","args":[120,29,54,1,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["动摇的决心"]},{"op":"place_name","args":["寿春议事厅"]},{"op":"dialog","args":["&王凌\n到底是怎么回事？黄华那边怎么久久没有\n回信？\n&王凌\n等一下，莫非他去密告了？"]},{"op":"delay","args":[5]},{"op":"actor_appear","args":[566,95,54,3,0]},{"op":"actor_move","args":[0,566,0,48,54,3]},{"op":"actor_action","args":[566,6]},{"op":"dialog","args":["&士兵01\n大事不好了！太傅已经知道计画，现在\n率领大军南下直往寿春。"]},{"op":"actor_action","args":[120,0]},{"op":"dialog","args":["&王凌\n该死！黄华那家伙果然去告密了！现在\n情况已经骑虎难下，只能和司马懿拚了！\n&士兵01\n可是圣上有下诏说，愿意赦免您一切的\n罪行。\n&王凌\n赦免老夫…嗯…"]},{"op":"actor_action","args":[120,0]},{"op":"dialog","args":["&士兵01\n另外太傅还有一封来信，说要给您看。\n&王凌\n好，老夫看看。"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&王凌\n终究他还是有念及老夫和他的旧情…只是\n曹爽当初相信他也落得满门抄斩的命运，\n老夫可以相信他？\n&王凌\n就算不相信他，老夫又能怎么样呢？老夫\n手中的军队可以和他抗衡？\n&王凌\n也罢，就看司马懿会不会守信用吧。"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[63]},{"op":"change_scene","args":[2,65535,65535,18,65535]},{"op":"actor_appear","args":[93,34,54,1,0]},{"op":"actor_appear","args":[94,48,43,2,0]},{"op":"actor_appear","args":[130,53,43,2,0]},{"op":"actor_appear","args":[95,48,69,0,0]},{"op":"actor_appear","args":[556,53,69,0,0]},{"op":"actor_appear","args":[120,48,54,3,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["寿春一叛"]},{"op":"place_name","args":["魏军营帐"]},{"op":"dialog","args":["&司马懿\n王凌！你图谋拥立楚王造反，你可知罪？\n&王凌\n知罪？老夫如果有罪怎可能因为这两封信\n就来了？还有这些军队是怎么回事？\n&司马懿\n正因为你不是两封信就能叫得来的人。\n&王凌\n你骗老夫！\n&司马懿\n老夫宁可骗你，不可以欺骗国家！\n&司马懿\n你之前和老夫要三根棺材钉子，老夫可以\n全部给你，你该明白要怎么做了？"]},{"op":"delay","args":[5]},{"op":"actor_action","args":[120,2]},{"op":"dialog","args":["&王凌\n司马懿！你这个奸贼居然还敢口口声声\n称国家？\n&王凌\n你敢说你诛杀曹爽，挟持天子叫做爱国？\n&王凌\n老夫本欲效法叔父过去诛杀董卓的义行，\n只可惜功败垂成…\n&王昶\n你这个叛贼还敢口口声声说是义行？\n&诸葛诞\n太傅拨乱反正，他有做什么对不起大魏的\n事情？"]},{"op":"actor_action","args":[120,0]},{"op":"dialog","args":["&王凌\n王昶就算了，毕竟他本来就是司马懿提拔\n的人。"]},{"op":"actor_face","args":[120,0,2]},{"op":"dialog","args":["&王凌\n只是诸葛诞你这家伙，居然早就暗地投靠\n了司马懿！真是丢你琅邪诸葛家的脸！\n&诸葛诞\n哼，我相信太傅能够让我大魏兴盛，效命\n太傅就是对我大魏尽忠。\n&王凌\n狗屁！司马懿诛杀曹氏亲族，控制皇上，\n把整个大魏当成他司马家的玩物，从哪一\n点可以看出他忠心？\n&诸葛诞\n你以救国为名，计画拥戴楚王，这样如何\n对得起明皇帝？\n&诸葛诞\n就算我们是儿女亲家，我也绝不允许你\n进行这种蔑视明皇帝法统的事！\n&王凌\n蠢才！你真的相信司马懿会忠于大魏？\n&王凌\n他只是利用文皇帝与明皇帝的托孤遗诏，\n将妨碍他的人一一铲除。顺便笼络你这种\n相信他的人，分化我们大魏忠臣。\n&王凌\n这手法就像他当年杀害曹爽一样！你是\n何晏的好友，当年在吏部有知人之明，\n现在你的识人之明到哪去了？\n&王凌\n诸葛诞，你好好想清楚，你以为司马家\n真的会对你推心置腹？\n&诸葛诞\n………"]},{"op":"dialog","args":["&司马懿\n哼哼…王凌啊…当初你叔父王允真的是\n为了大汉？还是因为和董卓的政争？"]},{"op":"actor_face","args":[120,0,3]},{"op":"dialog","args":["&司马懿\n诛除董卓一人之后，还将他全族屠灭，连\n他九十岁老母和十多岁的孙女都不放过。\n&司马懿\n现在你是为了大魏，还是想把老夫踢下去\n取而代之而已？你心里有数。"]},{"op":"actor_action","args":[93,6]},{"op":"dialog","args":["&司马懿\n司马懿纵然再不忠，也不允许你任意拥立\n新帝！先帝托孤的恩情，司马懿纵然万死\n也不能回报！\n&王凌\n哈哈哈，你的假面具还可以维持多久？\n我就在地狱等著看。\n&王凌\n就算你很会演，但是你的儿子真的会愿意\n继续当社稷之臣？\n&王凌\n大魏的未来…黯淡无光啊…"]},{"op":"actor_action","args":[93,0]},{"op":"actor_face","args":[120,3,1]},{"op":"dialog","args":["&王凌\n贾梁道（贾逵），王凌此生忠于大魏！\n只有你的神灵知道！"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&诸葛诞\n（太傅下手怎么这么狠？）\n&王昶\n（我受到太傅的提拔大恩，却又以忠臣\n自居，万一这样的价值观无法相容，到时\n该怎么办？）\n&司马师\n（天下迟早是我们司马家的，王凌你这\n蠢猪的愚行又能起什么作用？）\n&司马昭\n（又一个白白送死的家伙，难道你不知道\n和爹斗过的家伙都没好下场？）"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[63]},{"op":"change_scene","args":[1,30,0,65535,65535]},{"op":"change_scene","args":[0,23,65535,65535,65535]},{"op":"fade_out","args":[]},{"op":"caption","args":["公元二五一年，司马懿平定王凌的流产政变，王凌在知道生还无望后服毒自杀。",1,0,1]},{"op":"caption","args":["之后司马懿大军开进寿春，穷究猛追，深入调查，凡口供有提到的，全屠灭三族，",1,1,1]},{"op":"caption","args":["一时寿春变成人间地狱。",1,1,1]},{"op":"delay","args":[5]},{"op":"caption","args":["王凌和之前过世的令狐愚被剖开棺材，曝尸三日，",0,0,1]},{"op":"caption","args":["焚烧棺材中殉葬的印信后，再把尸体裸葬。",1,1,1]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[27]},{"op":"change_scene","args":[2,65535,65535,65,65535]},{"op":"actor_appear","args":[567,37,66,1,17]},{"op":"actor_appear","args":[568,59,66,3,17]},{"op":"actor_appear","args":[570,45,61,2,0]},{"op":"actor_appear","args":[644,45,66,0,10]},{"op":"actor_appear","args":[563,63,80,0,0]},{"op":"actor_appear","args":[564,61,83,0,0]},{"op":"actor_appear","args":[569,59,86,0,0]},{"op":"actor_appear","args":[565,51,86,0,0]},{"op":"actor_appear","args":[562,53,90,0,0]},{"op":"actor_appear","args":[563,50,89,0,0]},{"op":"fade_out","args":[]},{"op":"delay","args":[3]},{"op":"title_text","args":["智勇马隆"]},{"op":"place_name","args":["平阿城"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&文官\n兖州刺史令狐愚参与叛乱，虽然已经身故\n，但还是要曝尸三日，以儆效尤！\n&马隆\n等一下！"]},{"op":"actor_appear","args":[14,45,94,0,0]},{"op":"actor_move","args":[0,14,0,45,71,0]},{"op":"actor_action","args":[14,0]},{"op":"delay","args":[5]},{"op":"dialog","args":["&文官\n你是什么人？"]},{"op":"actor_action","args":[14,6]},{"op":"dialog","args":["&马隆\n在下马隆字孝兴，曾经是令狐刺史的\n门客。\n&文官\n你找死吗？令狐愚参与王凌叛乱，死有\n余辜，不想死就滚远点！\n&马隆\n您误会了，我不是要来为令狐刺史伸冤，\n只是想要为他收葬来尽一分心意。\n&文官\n这样啊…只是你真的是令狐刺史的门客？\n印象中我从来没有看过你。\n&马隆\n如果不是门客，谁愿意冒著这样的危险来\n为他收葬？您又有看到其他愿意为他收葬\n的门客？\n&文官\n嗯…那么就请三日后再来收葬他吧。\n&马隆\n多谢您的成全。\n&马隆\n（司马家即将取代大魏而代兴，我虽然不\n关心统治者是谁，但如果不能趁这样变局\n闯出一番事业，就实在是枉度一生。）"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[56]},{"op":"change_scene","args":[2,65535,65535,4,65535]},{"op":"actor_appear","args":[24,61,64,3,0]},{"op":"actor_appear","args":[139,61,58,3,0]},{"op":"actor_appear","args":[567,34,62,1,0]},{"op":"fade_out","args":[]},{"op":"delay","args":[3]},{"op":"title_text","args":["潜伏之时"]},{"op":"place_name","args":["洛阳东乡公主宅邸"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&士兵02\n公主，请您快点上路，不然小人很难\n交代。"]},{"op":"actor_action","args":[139,2]},{"op":"dialog","args":["&许仪\n你算什么东西敢对公主这样说话！\n&曹绫\n许仪，人家不过是奉命行事，别为难他。\n&曹绫\n我明白了，待我交代完一下事情马上就\n出发。"]},{"op":"actor_action","args":[567,6]},{"op":"dialog","args":["&士兵02\n公主，真的很对不起，小人也是奉命\n行事。\n&曹绫\n我知道，你不用太自责。"]},{"op":"actor_action","args":[567,0]},{"op":"actor_action","args":[139,0]},{"op":"delay","args":[5]},{"op":"actor_face","args":[24,0,0]},{"op":"actor_face","args":[139,0,2]},{"op":"actor_action","args":[139,2]},{"op":"dialog","args":["&许仪\n公主，那个司马懿实在是太过分了，他有\n什么权力将所有曹氏亲族迁往邺城？\n&曹绫\n这个时候，他就有这样的权力，毕竟王凌\n谋反牵涉到楚王曹彪。\n&曹绫\n只是我不相信这是刚好，而是司马懿利用\n这样的事情来扩大打击面。"]},{"op":"actor_action","args":[139,0]},{"op":"dialog","args":["&许仪\n呜呜，都是俺没用，要是当时武卫营兄弟\n们肯帮忙的话，就轮不到司马懿嚣张。\n&曹绫\n你也真蠢，当时的局势不是你一个人可以\n扭转的，不管是我或是曹爽都有责任。\n&曹绫\n现在只有听从司马懿的话，暂时等待机会\n，否则白白丢了性命，不是更划不来？\n&许仪\n公主…\n&曹绫\n相信我，我一定有回到洛阳的一天，\n到时候还要请你在我身边。\n&许仪\n是的，呜呜呜呜呜…\n&曹绫\n（邺城，真是令人怀念的地方…虽然那里\n充满著痛苦的回忆，但毕竟是我和娘亲\n度过童年的地方。）"]},{"op":"delay","args":[5]},{"op":"dialog","args":["公元二五一年，楚王曹彪因涉及王凌谋反\n一案而被命服毒自杀。司马懿更下令所有\n亲王公爵全部集中邺城并且严加看管。\n\n东乡公主曹绫也在迁往邺城的名单中，抵\n达邺城后她开始深居简出，再也没有任何\n动作。"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[63]},{"op":"change_scene","args":[2,39,65535,68,65535]},{"op":"actor_appear","args":[93,48,61,0,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["凤凰坠地"]},{"op":"place_name","args":["洛阳附近"]},{"op":"actor_action","args":[93,3]},{"op":"dialog","args":["&司马懿\n老夫打败了所有人，诸葛亮先老夫而死，\n曹爽被全族屠灭，曹绫无计可施。\n&司马懿\n老夫得到了所有该有的，究竟老夫还要\n什么？\n&曹操\n这正是我要问你的。"]},{"op":"actor_action","args":[93,0]},{"op":"delay","args":[5]},{"op":"play_sound","args":[9]},{"op":"actor_appear","args":[204,48,65,0,0]},{"op":"delay","args":[5]},{"op":"actor_face","args":[93,0,2]},{"op":"dialog","args":["&司马懿\n武帝？\n&曹操\n我从来没有当过皇帝一天，死前是魏王。\n&司马懿\n这是文帝在您去世后追封您的。\n&曹操\n呵呵，那个不肖子终究还是做了。\n&曹操\n刚才你在问自己到底想要什么，你要的\n不就和我一样。\n&司马懿\n懿从来没有任何篡夺的想法。\n&曹操\n那么为什么你要杀光子丹一家老小？彦云\n（王凌）一族也被你屠灭殆尽，甚至还逼\n死我的儿子？\n&司马懿\n那都只是为了保护老夫自己和司马家…\n&曹操\n当初我也是为了保护自己，把董承和伏完\n等人送到地狱去，请问我们有什么不一样\n的地方？\n&司马懿\n呵呵呵…哈哈哈…不，我们还是有不一样\n的地方。\n&曹操\n怎么说？\n&司马懿\n你以权术来杀人，弄得臭名满天下，众人\n怨恨不已。\n&司马懿\n老夫以礼教来杀人，反而名声传四海，\n大家推崇不止。\n&曹操\n那些都是你自己的一厢情愿，你真认为过\n了百年千年之后，你的所作所为会没有人\n发现？\n&司马懿\n过去刘家失去力量，由你曹家取而代之。\n今天曹家失去力量，我司马家为什么不可\n取而代之？\n&曹操\n这就是你的心底话？\n&司马懿\n不错！\n&曹操\n呵呵呵…真是愚蠢啊…"]},{"op":"delay","args":[5]},{"op":"actor_select","args":[0,204,0,0,0,0,6]},{"op":"actor_face","args":[93,0,0]},{"op":"dialog","args":["&司马懿\n武帝啊…武帝…你真是个奸雄，想当初\n老夫可是怕你怕得要死，你只要眉头一皱\n老夫就脑袋落地。\n&司马懿\n担任你幕僚之时，你每天把老夫按在\n地上打板子，用尽羞辱的方法折磨老夫\n，但老夫都挺过来了。\n&司马懿\n终于现在老夫可以把你的子孙踩在脚下\n，所有人的生死都在老夫一念之间，这\n武帝你又有想到过？\n&司马懿\n呵呵呵…呵呵…哈哈哈哈哈…"]},{"op":"actor_action","args":[93,10]},{"op":"play_music","args":[38,1]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[63]},{"op":"change_scene","args":[2,65535,65535,4,65535]},{"op":"actor_appear","args":[93,59,47,2,1]},{"op":"actor_appear","args":[94,56,60,0,0]},{"op":"actor_appear","args":[130,66,60,0,0]},{"op":"fade_out","args":[]},{"op":"delay","args":[3]},{"op":"place_name","args":["洛阳司马家"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&司马昭\n爹，您终于醒了…\n&司马师\n您居然昏倒在山上，若不是左右及时发现\n，恐怕早有危险了。\n&司马懿\n命数到了而已，没什么好大惊小怪的。\n&司马昭\n爹，您身体还很硬朗，绝对还可以…\n&司马懿\n老夫不打算浪费时间，趁现在赶快把要\n交代的事情交代清楚。\n&司马懿\n师儿，我们司马家的基业就交给你，老夫\n虽然想帮你清除掉所有的障碍，但看来是\n无法如愿了。"]},{"op":"actor_action","args":[94,6]},{"op":"dialog","args":["&司马师\n爹…我一定尽力…\n&司马懿\n曹爽和王凌虽然死了，但在你们面前的路\n还不是很平坦，中央有名士反抗，地方上\n还有毌丘俭和文钦等人。\n&司马懿\n那些都是我们司马家的威胁，早晚要铲除\n他们。\n&司马懿\n曹爽过去提拔政坛新秀的政策值得效法，\n老夫虽然之前因为他们是曹爽党羽而罢免\n他们，你们则要重新起用他们。\n&司马懿\n如此他们才会感激你的恩惠，对你效忠。\n&司马懿\n曹氏施行的中央集权政策要继续贯彻下去\n，毕竟我们的优势正是掌握中央。\n&司马懿\n记住！保护曹芳的托孤遗诏是铲除异己的\n最好武器，你们绝不能轻易废掉这个魁儡\n，否则就是自废武功！\n&司马师\n爹，我明白了！\n&司马懿\n好吧，你先下去，老夫有些话要单独对你\n弟弟说。\n&司马师\n是！"]},{"op":"actor_action","args":[94,0]},{"op":"delay","args":[5]},{"op":"actor_face","args":[94,0,3]},{"op":"actor_move","args":[0,94,0,30,60,3]},{"op":"actor_select","args":[0,94,0,0,0,0,6]},{"op":"wait_frame","args":[]},{"op":"actor_action","args":[94,15]},{"op":"delay","args":[5]},{"op":"dialog","args":["\n&司马昭\n爹…您要是不在了，我真的不知道该怎么\n办才好。像我这样胆小又懦弱的人…\n&司马懿\n昭儿，老夫过去也是像你一样，在武帝\n丞相府底下成天提心吊胆，周围的人都\n笑老夫是胆小鬼。\n&司马懿\n师儿在上次政变中表现出才能，所以老夫\n把大业都交给他。然而老夫更认定你才是\n能够支撑我们司马家的人。\n&司马懿\n不要害怕，相信你自己的才能，你不会比\n你大哥差的。\n&司马昭\n爹…呜呜呜…"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[63]},{"op":"change_scene","args":[1,30,0,65535,65535]},{"op":"change_scene","args":[0,5,65535,65535,65535]},{"op":"fade_out","args":[]},{"op":"caption","args":["公元二五一年，魏国太傅舞阳侯司马懿病逝于洛阳。魏帝追赠相国、",1,0,1]},{"op":"caption","args":["郡公，谥曰文贞，后改諡文宣。",1,1,1]},{"op":"delay","args":[5]},{"op":"caption","args":["因抗击诸葛亮，讨伐公孙渊而成为魏国的支柱，却也因此而夺取魏国的实权。",0,0,0]},{"op":"caption","args":["在高平陵之变和寿春之叛后完全掌控魏国。",1,1,1]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"change_scene","args":[1,30,0,65535,65535]},{"op":"change_scene","args":[0,1,65535,65535,65535]},{"op":"fade_out","args":[]},{"op":"caption","args":["司马懿过去在曹真面前发的毒誓，却在四十年后不幸应验，",0,0,1]},{"op":"caption","args":["司马家的子孙互相砍杀，死伤惨重，最终造成永嘉之乱的结果。",1,1,1]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"change_scene","args":[1,30,0,65535,65535]},{"op":"change_scene","args":[0,29,65535,65535,65535]},{"op":"fade_out","args":[]},{"op":"caption","args":["司马懿去世后，皇帝曹芳下诏，擢升卫将军司马师为抚军大将军，",0,0,1]},{"op":"caption","args":["录尚书事。司马懿的势力正式由司马师接掌。",1,1,1]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[50]},{"op":"change_scene","args":[2,65535,65535,25,65535]},{"op":"actor_appear","args":[94,64,60,2,0]},{"op":"actor_appear","args":[107,64,65,0,0]},{"op":"fade_out","args":[]},{"op":"delay","args":[3]},{"op":"title_text","args":["钟会自荐"]},{"op":"place_name","args":["洛阳司马家"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&司马师\n你说我有要用你的理由？"]},{"op":"actor_action","args":[107,6]},{"op":"dialog","args":["&钟会\n如果大将军想要当大魏的社稷之臣，那么\n您绝对用不著我。\n&钟会\n然而如果大将军想要成就大业，进而一统\n天下的话，那么大将军就必须要用我。\n&司马师\n你这么肯定我会用你，而不是把你依\n叛乱罪移送？\n&钟会\n您有王者的气息，更有王者的雄心，所以\n我认为您不会这样做。"]},{"op":"actor_action","args":[107,0]},{"op":"dialog","args":["&司马师\n你或许早就猜到我爹要我任用你们这些\n因为曹爽而被罢官的人吧。\n&司马师\n而你居然选在我要发出任用命令的前一刻\n过来毛遂自荐，真的是很狡猾。\n&钟会\n这么说大将军愿意用我？"]},{"op":"actor_face","args":[94,0,0]},{"op":"dialog","args":["&司马师\n我非常讨厌你这种厚颜无耻的小人，人家\n荀勖还知道去收葬曹爽，你做过什么？\n&司马师\n你父亲是大魏的忠臣，侍奉曹家超过三代\n，如今你却轻易抛弃自己的立场，你这种\n人真是不忠又不孝。\n&钟会\n忠诚值多少钱？过去父亲在我出世前尽力\n奉公，哪知道因为一个魏讽案就差点丢了\n脑袋。\n&钟会\n过去太傅为了我大魏抗击诸葛亮，到最后\n却还是被贬官，差点要成为地方官员一辈\n子。\n&钟会\n所以我决定要成为一个只要眼前利益的小\n人，而我看中的就是像您这样的王者。\n&司马师\n其实因为曹爽案而被罢免的名士中，我最\n想登用的是王弼，哪知道天妒英才，居然\n先故去了。\n&司马师\n结果我只能登用到你这样的小人，实在是\n让人感叹。\n&司马师\n不过，我和我爹不一样的地方在于，对小\n人我也可以包容，我想你或许也看到石苞\n被我重用的先例了。"]},{"op":"actor_face","args":[94,0,2]},{"op":"actor_action","args":[107,6]},{"op":"dialog","args":["&钟会\n感谢大将军给我这个机会！\n&钟会\n大将军，我建议您可以把任用我的事情编\n成这样的故事，就说您亲自到我家中来聘\n请我。\n&司马师\n为何？你不是说你不爱名声？\n&钟会\n我不爱可是别人爱，现在那些被罢免的人\n都还心有余悸，如果不做出这样的表示，\n他们怎么可能还愿意受聘？\n&司马师\n妙啊，你果然是有点本事，就照你说的话\n去做。"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[9]},{"op":"change_scene","args":[2,65535,65535,27,65535]},{"op":"actor_appear","args":[672,65,62,3,0]},{"op":"actor_appear","args":[71,57,62,1,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["夏侯玄的预言"]},{"op":"place_name","args":["洛阳大鸿胪府外"]},{"op":"dialog","args":["&许允\n恭喜你啊，这下太初你安全了。\n&夏侯玄\n怎么说？\n&许允\n现在太傅已经过世，你可以再也不用担心\n了。\n&夏侯玄\n你真是不懂事。司马懿是前辈长者，所以\n仍把我们当作是老朋友家的年轻晚辈来看\n待。\n&夏侯玄\n但是两个儿子司马师或是司马昭对我们\n可就不会这样包容了。\n&许允\n不会吧…\n&夏侯玄\n你等著好了，事情一定会照我想的发展。\n&夏侯玄\n（为什么会变成这样？难道我和子元\n的友情真的已经一去不复返？）"]},{"op":"delay","args":[10]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[4]},{"op":"change_scene","args":[2,65535,65535,64,65535]},{"op":"actor_appear","args":[162,53,61,0,0]},{"op":"actor_appear","args":[548,65,55,0,0]},{"op":"actor_appear","args":[590,58,61,0,0]},{"op":"actor_appear","args":[177,63,61,0,0]},{"op":"actor_appear","args":[167,68,61,0,0]},{"op":"actor_appear","args":[586,73,61,0,0]},{"op":"actor_appear","args":[163,78,61,0,0]},{"op":"actor_appear","args":[184,53,66,0,0]},{"op":"actor_appear","args":[194,58,66,0,0]},{"op":"actor_appear","args":[195,63,66,0,0]},{"op":"actor_appear","args":[196,68,66,0,0]},{"op":"actor_appear","args":[178,73,66,0,0]},{"op":"actor_appear","args":[169,78,66,0,0]},{"op":"fade_out","args":[]},{"op":"place_name","args":["建业寝宫"]},{"op":"title_text","args":["孙权之死"]},{"op":"dialog","args":["&孙权\n太子在哪里？\n&孙亮\n孩儿在。\n&孙权\n不是…不是说你！是和儿！\n&孙鲁班\n孙和目前是戴罪之身，自称无脸见陛下。\n&孙权\n这样啊…都是朕不对…都是朕不对…\n&孙鲁班\n（说什么都不能让太子再复位，不然他会\n回来找我报杀母之仇。）\n&孙鲁班\n（想想这两兄弟也真蠢，斗个半天都不知\n道被我玩弄在手掌心中，我那个笨老爹也\n是如此…）\n&孙峻\n（陛下老泪纵横的模样，完全不像是当年\n抗击曹操的英雄。）"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&孙权\n诸葛恪！"]},{"op":"actor_action","args":[167,6]},{"op":"dialog","args":["&诸葛恪\n微臣在！\n&孙权\n朕…以前…听过子瑜之言…说你不可大用\n，但…子远（孙峻）昨日大力…保举你，\n说当朝官员…无人…胜过你…\n&孙权\n朕就把亮儿托付给…你…望你改变…你\n刚愎自用…的个性。\n&诸葛恪\n微臣不胜惶恐。"]},{"op":"actor_action","args":[167,0]},{"op":"dialog","args":["&诸葛恪\n（哈哈，现在看谁振兴了诸葛家，我终于\n爬到和二叔相同的位子，看看谁只能躲在\n西川当个小小参谋！）\n&孙权\n众臣…大吴的江山就…托付给…各位了…\n&孙鲁班\n父皇啊…呜呜呜…\n&孙鲁班\n（哭逼真点，反正老头死了就可以和孙峻\n双宿双飞。只是这个诸葛恪实在是很碍眼\n，如果没他，天下就是我姓全的。）\n&孙权\n父亲、兄长、姊姊、练师、公瑾、子敬\n、子布、子明还有好多朕怀念的人，到\n那边可以再看到你们？\n&孙权\n伯言、子据、登儿、霸儿…你们不要怨恨\n朕，朕真的好后悔，好后悔…呜呜呜…"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[4]},{"op":"change_scene","args":[1,30,0,65535,65535]},{"op":"change_scene","args":[0,10,65535,65535,65535]},{"op":"fade_out","args":[]},{"op":"caption","args":["公元二五二年，东吴皇帝孙权病逝于建业，谥曰大皇帝。",1,0,1]},{"op":"delay","args":[5]},{"op":"caption","args":["孙权接掌江东，重用二张，信赖周瑜鲁肃等名将，赤壁抗击曹操成功，",0,0,1]},{"op":"caption","args":["袭取荆州，夷陵战胜刘备，终于奠定建国基业。",1,1,1]},{"op":"delay","args":[5]},{"op":"caption","args":["然而晚年成立校事特务，立嗣问题造成内斗，最后滥杀大臣尽失人心，",0,0,1]},{"op":"caption","args":["终于导致东吴国力直线下滑，种下灭亡远因。",1,1,1]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[62]},{"op":"change_scene","args":[2,65535,65535,51,65535]},{"op":"actor_appear","args":[68,51,29,2,0]},{"op":"actor_appear","args":[71,41,52,1,0]},{"op":"actor_appear","args":[578,41,57,1,0]},{"op":"actor_appear","args":[551,41,62,1,0]},{"op":"actor_appear","args":[579,41,67,1,0]},{"op":"actor_appear","args":[94,51,49,0,0]},{"op":"actor_appear","args":[99,65,52,3,0]},{"op":"actor_appear","args":[130,65,57,3,0]},{"op":"actor_appear","args":[580,65,62,3,0]},{"op":"actor_appear","args":[589,65,67,3,0]},{"op":"fade_out","args":[]},{"op":"place_name","args":["洛阳宫殿"]},{"op":"title_text","args":["司马师进兵"]},{"op":"actor_action","args":[94,6]},{"op":"dialog","args":["&司马师\n陛下！现今吴逆新丧，群贼无首，本就是\n发兵的大好时机。而吴贼不知据守，居然\n敢兴兵挑衅，现在不发兵更待何时？\n&司马师\n镇东将军诸葛诞提出建议，派王昶进攻\n江陵，毌丘俭袭击武昌牵制长江上游的\n军队。\n&司马师\n我们再遴选精锐，袭击东兴两城，必可大\n获全胜。\n&司马师\n（自古以来就没有顾命之臣地位可被继承\n的事情，我更不能继续长久依靠父亲的威\n望。）\n&司马师\n（利用这场战争来建立属于自己的战功和\n威望才是长久之计，公休的建议正是来得\n恰到好处。）"]},{"op":"actor_action","args":[94,0]},{"op":"delay","args":[5]},{"op":"dialog","args":["&曹芳\n嗯…那么众卿有什么意见？"]},{"op":"actor_face","args":[589,6,0]},{"op":"dialog","args":["&傅嘏\n臣以为这个计画大有问题，吴贼贼首刚刚\n过世，现在正是上下同心。\n&傅嘏\n如果贼人用船舰防守重要港口，用重兵\n守城，我们横渡长江的计画将受阻。\n&傅嘏\n再说我们的侦查部队是否对敌人战力作了\n正确的评估？如果没有就是凭运气打仗，\n实在不是作战的正规谋略。\n&曹芳\n尚书说得有道理，大将军你还是暂时不要\n出兵吧。"]},{"op":"actor_face","args":[589,6,3]},{"op":"delay","args":[5]},{"op":"actor_action","args":[94,6]},{"op":"dialog","args":["&司马师\n皇上！天赐的进攻机会就要让他溜掉？\n这样对得起先帝的托付？\n&曹芳\n这……\n&李丰\n（这和曹爽过去发动征蜀有什么两样？\n司马家父子简直就是小偷！）"]},{"op":"actor_action","args":[71,0]},{"op":"dialog","args":["&夏侯玄\n子元！这是对皇上说话的态度？"]},{"op":"actor_action","args":[71,0]},{"op":"actor_face","args":[94,2,3]},{"op":"dialog","args":["&司马师\n哼！我爱怎么说话还不需要你教！圣上都\n没说话了，你凭什么插嘴！\n&司马师\n还有我现在是大将军，请你以后说话不要\n直接称呼我的表字。\n&司马孚\n咳…子元，太初乃名将之后，之前你们还\n有姻亲关系，难道说话不能客气点？"]},{"op":"actor_face","args":[94,6,1]},{"op":"dialog","args":["&司马师\n对不起，叔父！是我失礼了。"]},{"op":"actor_face","args":[94,6,3]},{"op":"dialog","args":["&司马师\n也向大鸿胪您赔不是。\n&曹芳\n大家都是忠心为国嘛，不要介意。\n&曹芳\n关于大将军的作战计画，朕即刻批准，\n希望能一举荡平吴逆。"]},{"op":"actor_face","args":[94,6,0]},{"op":"dialog","args":["&司马师\n谢皇上！\n&夏侯玄\n（子元嚣张跋扈，和过去浮华友时代\n的他实在差太多了，为什么权力会让人\n变成这个样子？）\n&李丰\n（虽然司马家拉拢我，但是我的心还是向\n著夏侯玄，司马师那目中无人的态度实在\n是让人看不下去。）\n&张缉\n（哼！敢对我女婿这样说话，我一定要\n除掉你这个逆贼。）"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[62]},{"op":"change_scene","args":[1,30,0,65535,65535]},{"op":"change_scene","args":[0,34,65535,65535,65535]},{"op":"fade_out","args":[]},{"op":"caption","args":["公元二五二年，曹魏帝国向东吴发动大规模攻击，",1,0,1]},{"op":"caption","args":["王昶等三路大军分头并进，开始攻向东吴各重要据点。",1,1,1]},{"op":"delay","args":[5]},{"op":"caption","args":["征南大将军王昶攻击南郡，镇南将军毌丘俭攻击武昌（江夏郡），",0,0,1]},{"op":"caption","args":["征东将军胡遵和镇东将军诸葛诞则率领七万大军攻打东兴。",1,1,1]},{"op":"delay","args":[5]},{"op":"caption","args":["东吴太傅诸葛恪听到消息，立刻率军四万人，昼夜不停赶往援救东兴。",0,0,1]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[55]},{"op":"change_scene","args":[2,65535,65535,21,65535]},{"op":"actor_appear","args":[167,48,67,0,0]},{"op":"actor_appear","args":[177,61,54,3,0]},{"op":"actor_appear","args":[172,61,49,3,0]},{"op":"actor_appear","args":[173,61,44,3,0]},{"op":"actor_appear","args":[179,61,39,3,0]},{"op":"actor_appear","args":[169,36,54,1,0]},{"op":"actor_appear","args":[166,36,49,1,0]},{"op":"actor_appear","args":[181,36,44,1,0]},{"op":"actor_appear","args":[196,36,39,1,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["东兴之战"]},{"op":"place_name","args":["吴军营帐"]},{"op":"dialog","args":["&诸葛恪\n曹贼王昶、胡遵、毌丘俭和诸葛诞兵分\n四路攻击，兵力总计超过七万以上，敌人\n这次可是卯足了全力。"]},{"op":"actor_face","args":[181,6,2]},{"op":"dialog","args":["&朱异\n敌人虽然众多，但是往来交通都倚靠浮桥\n，如果我们集中攻击浮桥，必可使得他们\n进退两难。\n&诸葛恪\n季文说得好，这次攻击的重点就放在\n浮桥上。"]},{"op":"actor_face","args":[181,0,1]},{"op":"actor_face","args":[166,6,2]},{"op":"dialog","args":["&丁奉\n太傅，我们现在的行动实在太过缓慢，\n如果贼军占领有利地形便很难对抗，\n我建议让我率领自己的部曲先行作战。\n&诸葛恪\n好！承渊英勇过人，实在是我大吴现今\n第一武将。"]},{"op":"actor_face","args":[166,0,1]},{"op":"delay","args":[5]},{"op":"dialog","args":["&诸葛恪\n倒是…陆抗那家伙跑到哪去了？不是命令\n他过来这边集合，怎么都没看见人影？\n&全怿\n该不会吓得躲起来了？\n&诸葛恪\n如果他敢这样抗命，就算他父亲是陆伯言\n，我也饶不了他。"]},{"op":"delay","args":[5]},{"op":"actor_face","args":[169,0,2]},{"op":"dialog","args":["&施绩\n不可能的，幼节忠心爱国，应该只是路程\n稍微耽搁了一下。"]},{"op":"actor_action","args":[167,2]},{"op":"dialog","args":["&诸葛恪\n是吗？还是他打从心底看不起我这个\n太傅？"]},{"op":"actor_action","args":[167,0]},{"op":"delay","args":[5]},{"op":"actor_face","args":[169,0,1]},{"op":"actor_appear","args":[165,49,19,2,0]},{"op":"actor_appear","args":[220,52,19,2,0]},{"op":"actor_move","args":[0,165,0,49,54,2]},{"op":"actor_move","args":[0,220,0,54,54,2]},{"op":"actor_action","args":[165,0]},{"op":"actor_action","args":[220,0]},{"op":"delay","args":[5]},{"op":"actor_action","args":[165,6]},{"op":"dialog","args":["&陆抗\n太傅，请恕陆抗来迟！\n&诸葛恪\n哼！大敌当前居然还敢迟到，奋武将军\n你好大的官威。\n&陆抗\n我先去了会稽一趟，因为那里有我军这场\n作战获胜的关键。\n&诸葛恪\n获胜的关键？\n&陆抗\n是的，各位还听过甘兴霸将军的传奇吧。\n&丁奉\n我还亲自参与呢，当时跟随甘将军在濡须\n以百人精锐部队偷袭曹营全身而退，我军\n上下都为之赞叹。\n&陆抗\n现在我把这位甘将军带回来了。\n&诸葛恪\n他在哪？甘将军不是已经死很久了？\n&陆抗\n就是我身旁这位。\n&陆抗\n她是甘兴霸的孙女，因为继承祖父的名字\n，所以也叫甘宁。\n&甘宁\n（哈欠）陆抗，我实在是没有必要来参加\n这种无聊的会议吧。\n&诸葛恪\n她真的这么厉害？\n&唐咨\n哈哈哈，这个小女孩是甘宁，那我就是\n吕布了。"]},{"op":"actor_face","args":[165,0,0]},{"op":"actor_select","args":[0,220,0,0,0,0,6]},{"op":"delay","args":[5]},{"op":"actor_appear","args":[220,64,39,3,0]},{"op":"actor_face","args":[179,0,1]},{"op":"dialog","args":["&甘宁\n吕布有多厉害我是不知道，不过你这条\n小命保不保得住只在我一念之间。\n&唐咨\n快快快…快救我！\n&陆抗\n太傅，现在可以知道她的厉害了吧。\n&诸葛恪\n承渊，这场作战就带她去吧。"]},{"op":"actor_face","args":[220,0,2]},{"op":"actor_face","args":[165,0,2]},{"op":"actor_face","args":[166,6,2]},{"op":"dialog","args":["&丁奉\n遵命。\n&丁奉\n（回想当初锦帆贼被张辽全灭，甘兴霸也\n病死，没想到我还有机会和甘兴霸的后人\n共事。）\n&诸葛恪\n如果她真是甘宁的话，随行应该会很有\n帮助。\n&诸葛恪\n（这个小女孩真的有这样的本事？这种\n荒谬的事情居然也相信，看来吴郡陆家\n真是后继无人了。）\n&陆抗\n（太傅完全不知道甘宁的厉害，她真的\n像是父亲说的那样，完全不是人…）"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[37]},{"op":"change_scene","args":[2,65535,65535,73,65535]},{"op":"actor_appear","args":[166,41,50,2,0]},{"op":"actor_appear","args":[220,46,50,2,0]},{"op":"actor_appear","args":[258,35,55,0,0]},{"op":"actor_appear","args":[259,40,55,0,0]},{"op":"actor_appear","args":[260,45,55,0,0]},{"op":"actor_appear","args":[261,50,55,0,0]},{"op":"actor_appear","args":[262,55,55,0,0]},{"op":"actor_appear","args":[263,60,55,0,0]},{"op":"actor_appear","args":[264,65,55,0,0]},{"op":"actor_appear","args":[265,70,55,0,0]},{"op":"actor_appear","args":[266,75,55,0,0]},{"op":"actor_appear","args":[267,80,55,0,0]},{"op":"actor_appear","args":[268,35,60,0,0]},{"op":"actor_appear","args":[269,40,60,0,0]},{"op":"actor_appear","args":[270,45,60,0,0]},{"op":"actor_appear","args":[271,50,60,0,0]},{"op":"actor_appear","args":[272,55,60,0,0]},{"op":"actor_appear","args":[273,60,60,0,0]},{"op":"actor_appear","args":[306,65,60,0,0]},{"op":"actor_appear","args":[307,70,60,0,0]},{"op":"actor_appear","args":[308,75,60,0,0]},{"op":"actor_appear","args":[309,80,60,0,0]},{"op":"delay","args":[5]},{"op":"fade_out","args":[]},{"op":"title_text","args":["丁奉奋短兵"]},{"op":"place_name","args":["东关 河边"]},{"op":"actor_action","args":[166,0]},{"op":"dialog","args":["&丁奉\n各位！你们看见贼营在我们面前笙歌庆祝\n是不是很不爽？\n&步兵1\n不爽透了！\n&步兵2\n宰了他们！\n&丁奉\n现在天气冷得要命，为什么我们要在\n这里？\n&步兵1\n抢钱！抢粮！抢娘们！\n&步兵2\n杀！杀！杀！\n&丁奉\n没错，夺取侯爵！领取赏赐！就在今日！\n&丁奉\n现在脱掉盔甲！扔掉长矛，手上只要拿\n大刀和盾牌。\n&甘宁\n喔…（脱衣）"]},{"op":"actor_face","args":[166,0,1]},{"op":"dialog","args":["&丁奉\n等一下！你不用脱！（一个十来岁的\n小女孩，脱了也没什么看头。不过再\n过个十年的话也许……）\n&甘宁\n嗯？"]},{"op":"actor_face","args":[166,0,0]},{"op":"actor_face","args":[220,0,0]},{"op":"delay","args":[3]},{"op":"dialog","args":["&胡遵\n你们看见了吗？大冬天打赤膊，是要表演\n猛男秀给我们看？\n&诸葛诞\n哇哈哈哈哈，这种部队就想来挑战我们，\n真是快笑死我了。\n&胡遵\n队伍里还有个小女孩，吴贼看来是真的\n没人了。\n&诸葛诞\n来来来，再喝两杯，天冷喝酒真是享受。\n&胡遵\n记得别杀那个小女孩，等下绑到我帐下。\n&诸葛诞\n你该不会对小女孩也有兴趣吧…\n&胡遵\n别误会了，我不是萝莉控，我只是有点\n喜欢小孩的女权主义者。\n&诸葛诞\n那不就是萝莉控？"]},{"op":"delay","args":[3]},{"op":"dialog","args":["&丁奉\n弟兄们，听到对面恶心的笑声了吧？\n&丁奉\n现在我们就过去让他们笑不出来！\n&甘宁\n我的对手就是眼前那些饮酒作乐的废物？\n哼哼，实在是太无趣了。\n&丁奉\n（这说话口气和好战的个性，真的就是\n甘兴霸再世没错。）"]},{"op":"delay","args":[3]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[37]},{"op":"change_scene","args":[1,30,0,65535,65535]},{"op":"change_scene","args":[0,20,65535,65535,65535]},{"op":"fade_out","args":[]},{"op":"caption","args":["魏军对于丁奉的攻击毫无防备，东吴军杀声震天，",1,0,1]},{"op":"caption","args":["直砍向魏军前哨各营，魏军四散逃走。\n",1,1,1]},{"op":"delay","args":[5]},{"op":"caption","args":["魏军争先奔向浮桥，浮桥承受不住人马奔腾，忽然断裂，",0,0,1]},{"op":"caption","args":["魏军跌落水中无数，没有跌落的也互相践踏，死伤数万人。",1,1,1]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[95]},{"op":"change_scene","args":[2,65535,65535,1,65535]},{"op":"actor_appear","args":[166,56,53,1,0]},{"op":"actor_appear","args":[220,56,58,1,0]},{"op":"actor_appear","args":[258,55,48,0,10]},{"op":"actor_appear","args":[105,52,58,2,10]},{"op":"actor_appear","args":[260,51,53,0,10]},{"op":"actor_appear","args":[261,66,34,0,10]},{"op":"actor_appear","args":[262,69,36,2,10]},{"op":"actor_appear","args":[263,76,45,1,10]},{"op":"actor_appear","args":[264,67,41,2,10]},{"op":"actor_appear","args":[265,55,25,3,10]},{"op":"actor_appear","args":[266,45,55,3,10]},{"op":"actor_appear","args":[267,48,57,1,10]},{"op":"actor_appear","args":[268,76,69,2,10]},{"op":"actor_appear","args":[269,72,63,0,10]},{"op":"actor_appear","args":[270,78,45,1,10]},{"op":"actor_appear","args":[271,68,53,2,10]},{"op":"actor_appear","args":[167,61,58,3,0]},{"op":"actor_appear","args":[165,61,53,3,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["甘宁再现"]},{"op":"place_name","args":["东关 魏军营帐"]},{"op":"dialog","args":["&诸葛恪\n承渊果然英勇无比，杀得曹贼尸横遍野。\n&丁奉\n这里的尸体不是我制造的，全都是这位\n小甘宁杀的。\n&丁奉\n丁奉真的是大开眼界，就算是甘兴霸本人\n也没有这种杀人如斩草的能力。\n&丁奉\n当时在肉搏战的时候，她以我们完全跟不\n上的速度杀到敌营，敌人的防线被她一个\n人冲破。\n&丁奉\n我军本来居于人数劣势，就是因为她的\n英勇表现，振奋了士气才得以破敌。\n&诸葛恪\n怎么可能…等一下…你身后的那个尸体\n该不会是韩综？\n&甘宁\n那个垃圾？只知道他和我交手不到一回合\n就躺平了。\n&陆抗\n你可立大功了，那韩综是我大吴头号叛将\n，当年大皇帝恨他可是恨得牙痒痒。\n&诸葛恪\n嗯…赶快割下韩综的头献祭太庙。\n&诸葛恪\n（话说回来，这个叫甘宁的真是厉害，\n我有这样的猛将还怕什么？）\n&诸葛恪\n（接下来我应该来场漂亮的北伐，只要\n北伐成功，我将可以超越二叔，成为这\n时代最亮眼的巨星。）"]},{"op":"delay","args":[3]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[37]},{"op":"change_scene","args":[2,65535,65535,30,65535]},{"op":"actor_appear","args":[166,45,36,2,0]},{"op":"actor_appear","args":[220,50,41,2,0]},{"op":"actor_appear","args":[165,45,41,2,0]},{"op":"actor_appear","args":[590,50,46,2,0]},{"op":"actor_appear","args":[167,45,46,2,0]},{"op":"actor_appear","args":[563,33,72,1,0]},{"op":"actor_appear","args":[564,33,67,1,0]},{"op":"actor_appear","args":[565,32,61,1,0]},{"op":"actor_appear","args":[573,32,55,1,0]},{"op":"actor_appear","args":[562,34,50,1,0]},{"op":"actor_appear","args":[575,34,44,1,0]},{"op":"actor_appear","args":[574,34,38,1,0]},{"op":"actor_appear","args":[560,37,55,1,0]},{"op":"actor_appear","args":[559,35,33,1,0]},{"op":"actor_appear","args":[571,35,27,1,0]},{"op":"actor_appear","args":[561,35,21,1,0]},{"op":"actor_appear","args":[258,62,83,3,0]},{"op":"actor_appear","args":[259,62,78,3,0]},{"op":"actor_appear","args":[260,62,73,3,0]},{"op":"actor_appear","args":[261,62,68,3,0]},{"op":"actor_appear","args":[262,62,63,3,0]},{"op":"actor_appear","args":[263,62,58,3,0]},{"op":"actor_appear","args":[264,62,53,3,0]},{"op":"actor_appear","args":[265,62,48,3,0]},{"op":"actor_appear","args":[266,62,43,3,0]},{"op":"actor_appear","args":[267,62,32,3,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["诸葛恪的雄心"]},{"op":"place_name","args":["建业街头"]},{"op":"dialog","args":["&步兵1\n太傅！太傅！太傅！\n&女子\n这就是太傅吗？长得好帅喔！\n&男子\n可恶啊，我没有女朋友都是太傅害的。\n&老人\n江东过去英豪唯一可以和太傅比美的，\n大概也只有美周郎了。\n&商人\n现在或许可以考虑卖关于太傅的周边\n商品…\n&男童\n我长大也要像太傅那样！\n&旅人\n废除校事，免除过重田赋，撤销关税，\n一扫孙权在位时的阴霾，这国家似乎又\n有希望了。"]},{"op":"delay","args":[8]},{"op":"dialog","args":["&步兵1\n不要挤！不要挤！待会午时三刻有太傅的\n签名会，请依顺序排队！\n&诸葛恪\n………\n&诸葛恪\n（爽死了，我居然受欢迎到这种地步。）\n&甘宁\n这么无聊的游戏要玩到什么时候？被人家\n当猴子看很高兴？"]},{"op":"actor_face","args":[165,0,1]},{"op":"dialog","args":["&陆抗\n小甘宁…忍耐点，毕竟这些人都是来迎接\n我们凯旋的。"]},{"op":"actor_face","args":[165,0,2]},{"op":"actor_face","args":[590,0,3]},{"op":"actor_face","args":[167,6,0]},{"op":"dialog","args":["&诸葛恪\n各位乡亲父老，感谢大家的支持，诸葛恪\n真是非常高兴。"]},{"op":"actor_action","args":[167,0]},{"op":"dialog","args":["&诸葛恪\n接下来我要宣布一件令人振奋的消息。\n&诸葛恪\n曹贼经过这次兵败不堪一击，我决定要发\n动空前规的北伐，将长久以来不断侵略\n我大吴的曹贼一口气消灭。\n&滕胤\n等一下！太傅你疯了吗？\n&滕胤\n你受到的是伊尹、霍光之托，回到京师\n更应该安邦定国，稍加休息。\n&滕胤\n在差役征战之后再度兴师，民力已疲，\n财力已竭，敌人也有所准备。如果攻击\n不克，将使前功尽弃。\n&滕胤\n况且出征是件大事，如果大家都认为不行\n，光靠你一个人怎么能办到？"]},{"op":"actor_face","args":[167,0,1]},{"op":"dialog","args":["&诸葛恪\n大家都认为不可以，是因为无法了解我的\n谋略，只想苟且偷安，想不到你也是抱有\n相同想法，真令人遗憾。\n&诸葛恪\n现今曹芳昏庸拙劣，司马懿遭到天诛，\n两个儿子年纪幼小，能力薄弱。\n&诸葛恪\n现在敌营人民离心离德，我凭靠帝国力量\n，掌握战胜余威，大军所指，攻无不克。\n&滕胤\n………\n&诸葛恪\n每次我拜读叔父的出师表，未尝不喟然\n伤感，早晚不能安心。\n&诸葛恪\n我认为必须要立即采取行动，就算不幸\n失败，也不至于愧对先帝的托付。"]},{"op":"actor_face","args":[167,0,0]},{"op":"dialog","args":["&陆抗\n先不说劳役部分，曹贼大将军司马师就\n我所知现年四十又六，如何称作幼小？\n&陆抗\n而根据我估计，光是在淮南一带，敌人\n守军就超过十五万，以此估计全国兵力\n至少在六十五万上下。\n&陆抗\n现在就算把我大吴可动员的兵力抽光，\n大概也不超过二十万，试问如何作战？\n&诸葛恪\n司马师徒有年纪，智慧却与孩童相类，\n敌人人数虽多，却只是乌合之众。\n&诸葛恪\n我的文告请你再看仔细点，不要抓住一点\n语病就来指责。\n&男子\n太傅！太傅！太傅！\n&女子\n太傅！太傅！太傅！\n&陆抗\n（完蛋了，这次北伐如果没有办法阻止，\n一定会有空前的劫难，哪怕甘宁再勇猛\n也无用武之地。）\n&甘宁\n………\n&诸葛恪\n（我就知道像陆抗这样的吴中世族会捣乱\n，这些人从来就没有进取之心，只想巩固\n自己的领地和部曲。）\n&诸葛恪\n（我要利用这场北伐，把淮泗人和江东人\n的势力给整合起来，如此我大吴才可以发\n挥最完整的战斗能力。）\n&诸葛恪\n（大皇帝没办法整合不同族群北伐，二叔\n也无法好好利用益州人的力量，只有我可\n以挑战这样的创举。）\n&诸葛恪\n（若是这次北伐成功，我就可以超越这\n两人，成为这时代真正的胜利者。）"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[16]},{"op":"change_scene","args":[2,65535,65535,39,65535]},{"op":"actor_appear","args":[0,67,59,0,0]},{"op":"actor_appear","args":[5,66,47,0,0]},{"op":"actor_appear","args":[848,57,32,2,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["宁随的预言"]},{"op":"place_name","args":["涪县姜维宅"]},{"op":"delay","args":[8]},{"op":"dialog","args":["&女子1\n以上是关于东兴之战的报告，魏国损失\n非常惨重，新任大将军司马师的权力也\n严重动摇。\n&姜维\n没想到孙权死后，东吴还能有这样的战力\n，诸葛恪真是做得有声有色。\n&宁随\n你现在暂时留在国内，等到有事的时候\n再叫你。\n&女子1\n是。"]},{"op":"actor_select","args":[0,848,0,0,0,0,6]},{"op":"wait_frame","args":[]},{"op":"delay","args":[8]},{"op":"actor_face","args":[5,0,2]},{"op":"dialog","args":["&宁随\n伯约是不是认为这是北伐的机会？\n&姜维\n没错，司马懿死后，司马师继承他的位子\n本来就名不正言不顺。\n&姜维\n司马师为了巩固自己的权力，发动大军\n征吴却失败，现在想必是忙得焦头烂额。\n&姜维\n更重要的是，伯济虽然和司马懿有过从属\n关系，但和司马师却毫无瓜葛，两边互信\n有限。\n&姜维\n现在出兵，司马师必定会对是否援救雍凉\n感到迟疑。\n&宁随\n伯约说得都对，现在真的是出兵的黄金\n时机，不过想过文伟这关，难呀…"]},{"op":"delay","args":[8]},{"op":"dialog","args":["&姜维\n大将军应该也不是这么不通情达理，\n为什么不让我试试？\n&宁随\n现在他才刚被允许开府，正在汉寿那地方\n忙得不可开交，他不可能会允许你在这时\n出兵。\n&姜维\n可是，不试试看怎么知道？\n&宁随\n听我的…不久之后，什么问题都没了。"]},{"op":"delay","args":[8]},{"op":"dialog","args":["&姜维\n幼常，你这是什么意思？"]},{"op":"actor_face","args":[5,0,0]},{"op":"dialog","args":["&宁随\n没什么，就当作是我不专业的预言吧。"]},{"op":"delay","args":[8]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[34]},{"op":"change_scene","args":[2,65535,65535,4,65535]},{"op":"actor_appear","args":[124,58,68,3,0]},{"op":"actor_appear","args":[205,50,68,1,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["费郭之交"]},{"op":"place_name","args":["汉寿 大将军府"]},{"op":"dialog","args":["&费祎\n这两年在大汉过得如何？"]},{"op":"actor_action","args":[205,6]},{"op":"dialog","args":["&郭循\n除了气候有点不适应外，其他都已经习惯\n了。"]},{"op":"actor_action","args":[205,0]},{"op":"dialog","args":["&郭循\n只是…为什么大将军会对我如此关心？\n&费祎\n为什么呢？其实我也不太清楚，或许是\n让我想起过去一个人离乡背井，从荆州\n前往益州发展的事情吧。\n&费祎\n那时候面对陌生环境的我真的很惶恐，\n不知道明天会发生什么事情。\n&郭循\n大将军也是辛苦了，没想到您也会有这样\n的经历。\n&费祎\n我们很多人都是这样苦过来的，所以你\n千万不要在这里感到孤独，多放宽心胸\n去和其他人交往。\n&郭循\n嗯……\n&费祎\n其实最近认识你之后才一直思考，是不是\n我坐上这个高位太久，让我忘记本来的待\n人方式。\n&费祎\n以前我还会为魏延和杨仪感情交恶的事情\n烦恼得睡不好觉。\n&费祎\n然而曾几何时，我居然拿那样恶劣的态度\n来对姜伯约…其实他也是一心为了我大汉\n好。\n&费祎\n虽然我还是不赞同他的北伐策略，但是用\n那样高压的态度对待他，现在怎么想都是\n我的过错。\n&郭循\n大将军…我认为还是有机会和好的，虽然\n我和他交情不深，但不认为他是个会记恨\n的人。\n&郭循\n或许你们两个人开诚布公，把心底的话\n说出来，所有的心结也就可以解开了。\n&费祎\n说得也是…实在是很感谢你…\n&费祎\n真对不起，这两年一直把你当成倾诉的\n对象，实在是因为这些话我不知道该对\n谁说。\n&费祎\n若不是奉宗提醒我可以找你的话，我恐怕\n到现在还是得将那些事情闷在心里。\n&郭循\n大将军…\n&费祎\n对了，以后叫文伟就好了，至少在私底下\n我们不该有这样的上下之别。\n&费祎\n明天是一年一度的元旦聚会，你就来参加\n一下吧，这样你或许可以认识更多人。\n&郭循\n嗯，我会参加的。\n&费祎\n（明天的聚会结束后，我也该调整一下对\n伯约的态度，希望能够化解我们两个人之\n间的心结。）\n&郭循\n（如今我待在蜀地也快三年了，如果再不\n立下功劳的话，家乡的亲人不知道会受到\n什么样的待遇。）\n&郭循\n（本来想要暗杀刘禅的，但是迟迟没有\n机会，看来只能杀眼前的这位了…）\n&郭循\n（然而他对我这么好，我真的下得了手\n杀他吗？）"]},{"op":"delay","args":[8]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[46]},{"op":"change_scene","args":[2,65535,65535,7,65535]},{"op":"actor_appear","args":[124,51,31,2,0]},{"op":"actor_appear","args":[205,38,45,1,0]},{"op":"actor_appear","args":[47,38,56,1,0]},{"op":"actor_appear","args":[40,38,64,1,0]},{"op":"actor_appear","args":[155,38,75,1,0]},{"op":"actor_appear","args":[55,66,45,3,0]},{"op":"actor_appear","args":[53,66,56,3,0]},{"op":"actor_appear","args":[652,66,64,3,0]},{"op":"actor_appear","args":[257,66,75,3,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["费祎遇刺"]},{"op":"place_name","args":["汉寿宴会厅"]},{"op":"actor_action","args":[124,5]},{"op":"dialog","args":["&费祎\n大家不要客气，尽量喝没有关系，今天是\n新年聚会，不要有什么顾忌。"]},{"op":"actor_face","args":[47,6,0]},{"op":"dialog","args":["&董厥\n那么就先敬大将军。"]},{"op":"actor_action","args":[124,0]},{"op":"dialog","args":["&费祎\n好好好，再来再来！\n&费祎\n孝先，你怎么不喝呢？还是在想故乡？"]},{"op":"actor_face","args":[205,6,0]},{"op":"dialog","args":["&郭循\n不，郭循本来还想，但是现在已经不想\n了。"]},{"op":"actor_face","args":[155,0,0]},{"op":"dialog","args":["&尹赏\n大将军，让这样的降将出席好吗？\n&费祎\n说什么话，他都已经是大汉的左将军，\n你们也该早点把他当自己人看待了。\n&尹赏\n这…\n&尹赏\n（太诡异了，今天士兵居然都被撤掉，\n就算是庆祝会也不该这么放松…）"]},{"op":"delay","args":[8]},{"op":"actor_move","args":[0,205,0,52,39,0]},{"op":"delay","args":[8]},{"op":"actor_action","args":[205,6]},{"op":"dialog","args":["&郭循\n大将军，三年来的时光，我一直在想自己\n能够做些什么。\n&费祎\n你先别急，等到时机成熟自然会让你跟著\n上阵立功。\n&郭循\n不…大将军您完全误会我的意思。\n&郭循\n我的意思是…要如何才能帮我大魏立功。\n&费祎\n你说什么？！等一下…难道你的投降…\n&郭循\n我很感谢大将军你对我的提拔，但是我还\n是想要为我大魏立功，至少可以庇荫我的\n孩子们。\n&郭循\n本来我的目标是圣上，但我总是没有办法\n靠近他一步，最后只能把目标放在你身上\n了。\n&费祎\n我明白了。只是你平时都有机会暗杀我，\n为什么要挑今天这个大庭广众？\n&郭循\n因为只有这样，才能让我的行动彰显在\n世人眼前。\n&费祎\n我看不是吧，而是你希望有人可以阻止你\n，只是看来你的希望落空了。\n&费祎\n过了这么久都没有一个守卫过来，我大概\n也明白是怎么回事了。\n&樊建\n大将军！\n&费祎\n不准过来，你们都是国家的重臣，有什么\n损伤我可不乐见。\n&费祎\n今天算是我气数已尽，希望你们日后能\n继续忠心辅佐圣上。\n&郭循\n大将军…\n&费祎\n动手吧！"]},{"op":"actor_action","args":[205,13]},{"op":"play_music","args":[34,1]},{"op":"delay","args":[8]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[46]},{"op":"change_scene","args":[1,30,0,65535,65535]},{"op":"change_scene","args":[0,1,65535,65535,65535]},{"op":"fade_out","args":[]},{"op":"caption","args":["公元二五三年元旦，蜀汉大将军费祎在汉寿的元旦聚会上，被降将郭循刺杀于座。",1,0,1]},{"op":"caption","args":["过去越隽太守张嶷曾经写信警告费祎要当心刺客，然费祎并未听从，终于受祸。",1,1,1]},{"op":"delay","args":[5]},{"op":"caption","args":["魏帝曹芳追封郭循为长乐乡侯，食邑千户，谥威侯；子袭爵，加拜奉车都尉。",0,0,1]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[13]},{"op":"change_scene","args":[2,65535,65535,50,65535]},{"op":"actor_appear","args":[49,52,77,0,0]},{"op":"actor_appear","args":[50,59,73,0,0]},{"op":"actor_appear","args":[0,52,56,2,0]},{"op":"actor_appear","args":[257,39,61,1,0]},{"op":"actor_appear","args":[40,65,61,3,0]},{"op":"actor_appear","args":[668,65,56,3,0]},{"op":"actor_appear","args":[55,39,56,1,0]},{"op":"actor_appear","args":[51,39,51,1,0]},{"op":"actor_appear","args":[47,39,46,1,0]},{"op":"actor_appear","args":[652,65,51,3,0]},{"op":"actor_appear","args":[155,65,46,3,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["新人事"]},{"op":"place_name","args":["成都 皇宫"]},{"op":"actor_action","args":[0,6]},{"op":"dialog","args":["&姜维\n陛下…大将军他…\n&刘禅\n朕已经知道了，没想到他会以这样的结局\n收场。"]},{"op":"delay","args":[5]},{"op":"actor_face","args":[257,6,2]},{"op":"dialog","args":["&樊建\n郭循在刺杀大将军的同时也自尽，似乎他\n一开始就有这样的决心。\n&姜维\n（这是怎么回事？为什么大家看我的眼神\n都充满著怀疑？难道是认为我和刺杀大将\n军的事情有关？）\n&董厥\n（姜维绝对有足够的动机刺杀大将军，\n我认为他绝脱离不了关系。）\n&诸葛瞻\n（这件事情谁得利，谁就是幕后黑手。）\n&尹赏\n（我相信伯约不会做这种事情，但其他人\n似乎不这样认为。）\n&谯周\n（只因为大将军阻止你发动战争就暗杀他\n，姜维你这个人实在是让我太失望了。）\n&郤正\n（我对姜维这个人不很熟，实在很难做出\n评价来。真要说的话，我不认为姜维会笨\n到用这么明显的方式杀人。）"]},{"op":"actor_face","args":[257,0,1]},{"op":"dialog","args":["&刘禅\n现在大将军已死，军政部分就交给卫将军\n，命你都督中外所有军事，以后军事作战\n方面你有权力可以自由决定一切。\n&姜维\n是！\n&姜维\n（本来应该很高兴没有人掣肘自己的战略\n，但现在却怎么也高兴不起来。）"]},{"op":"actor_face","args":[51,6,2]},{"op":"dialog","args":["&陈祗\n关于政事部分，臣以为卫将军军务繁忙，\n若是兼理政务，恐怕有影响军事上表现的\n可能。\n&刘禅\n嗯…侍中真是言之有理，加上之前吕乂\n过世后，尚书令工作一直悬缺。\n&刘禅\n朕现在就命你以侍中职守尚书令，并且加\n你为镇军将军。"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[13]},{"op":"change_scene","args":[1,30,0,65535,65535]},{"op":"change_scene","args":[0,29,65535,65535,65535]},{"op":"fade_out","args":[]},{"op":"caption","args":["蜀汉政治自从费祎死后开始出现巨大变动，",1,0,1]},{"op":"caption","args":["姜维虽取代费祎成为蜀汉最高军事长官，但是人在外地的他无法插手政事。",1,1,1]},{"op":"delay","args":[5]},{"op":"caption","args":["于是政治大权落到官位远低于他的陈祗手上，",0,0,1]},{"op":"caption","args":["自此蜀汉再也没有能将政权和军权一把抓起的权臣。",1,1,1]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[0]},{"op":"change_scene","args":[2,65535,65535,61,65535]},{"op":"actor_appear","args":[0,53,63,1,0]},{"op":"actor_appear","args":[51,58,63,3,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["高峰会面"]},{"op":"place_name","args":["成都尚书令府"]},{"op":"actor_action","args":[51,6]},{"op":"dialog","args":["&陈祗\n在下一直很久仰卫将军您呀，今日相见，\n实感荣幸。"]},{"op":"actor_action","args":[51,0]},{"op":"dialog","args":["&姜维\n之前孝兴的事情，承蒙尚书令相助，\n在下才要道谢。\n&陈祗\n别叫官名这么见外，请直呼在下的名或\n表字就行了。\n&陈祗\n之前关于大将军打压您的情况，在下大概\n也都听说了，实在是感到相当遗憾。\n&姜维\n请别这样说，大将军也是有他的考量，\n在下不会因此怨恨他。\n&陈祗\n别误会了，在下绝对相信您和这件事情\n没有关系。\n&陈祗\n在下要说的是，我们应该要合作，来避免\n过去那样的摩擦。\n&陈祗\n在下希望卫将军您能专心在外对付曹贼，\n而陈祗在内部负责让圣上和其他大臣能够\n理解您的行动，让您无后顾之忧。\n&姜维\n奉宗…在下和您并不相熟，为何要如此\n相助？\n&陈祗\n因为您是和在下不一样的人，在下是个\n缺乏行动力的人。而您却不同，纵面对\n大将军的重重限制，还是愿意做下去。\n&陈祗\n当在下看见您过去总是带著不满一万的\n军队在和曹贼作战，眼眶总不自觉地湿\n了。\n&陈祗\n所以在下获得圣上提拔后的第一件事，\n就是希望能够帮助像您这样的栋梁之才\n，让您不再被后方的事情搅扰。"]},{"op":"actor_action","args":[0,6]},{"op":"dialog","args":["&姜维\n您的诚意在下感受到了，在下真的很幸运\n能有像你这样诚实可靠的盟友。\n&陈祗\n这么说，您愿意和我结盟？\n&姜维\n是的，以后也请多指教。"]},{"op":"delay","args":[8]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[16]},{"op":"change_scene","args":[2,65535,65535,18,65535]},{"op":"actor_appear","args":[0,35,54,1,0]},{"op":"actor_appear","args":[9,46,45,2,0]},{"op":"actor_appear","args":[4,51,45,2,0]},{"op":"actor_appear","args":[3,56,45,2,0]},{"op":"actor_appear","args":[10,61,45,2,0]},{"op":"actor_appear","args":[13,66,45,2,0]},{"op":"actor_appear","args":[2,71,45,2,0]},{"op":"actor_appear","args":[32,76,45,2,0]},{"op":"actor_appear","args":[12,46,66,0,0]},{"op":"actor_appear","args":[17,51,66,0,0]},{"op":"actor_appear","args":[15,56,66,0,0]},{"op":"actor_appear","args":[1,61,66,0,0]},{"op":"actor_appear","args":[22,66,66,0,0]},{"op":"actor_appear","args":[5,71,66,0,0]},{"op":"actor_appear","args":[6,76,66,0,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["肩负重任"]},{"op":"place_name","args":["姜维军营帐"]},{"op":"dialog","args":["&姜维\n这到底是怎么回事？你真的不知情？"]},{"op":"actor_face","args":[5,6,3]},{"op":"dialog","args":["&宁随\n大将军遇刺身亡，卫将军你变成独揽军权\n的大将，就这么回事而已。\n&姜维\n天下会有这么巧合的事情，我从西平俘虏\n回来的将领会忽然变成刺客？\n&姜维\n现在朝廷所有怀疑的眼光都集中在我身上\n，那种感觉真是难受无比。\n&宁随\n我什么都不知道。\n&袁綝\n（我不认为是姜维干的，他一个远离\n政权的将领就算杀费祎，后继人也不\n会是他。）\n&廖化\n（我感觉毛毛的，原来姜维是会杀害和\n自己意见不同的人，这样看来，他岂非\n早晚干掉我？）"]},{"op":"actor_face","args":[5,0,0]},{"op":"delay","args":[5]},{"op":"actor_face","args":[3,6,3]},{"op":"dialog","args":["&柳隐\n不管事实是怎么样，大将军这个讨人厌的\n家伙不在了，今后北伐将不再有人掣肘不\n是吗？\n&柳隐\n老大，难道你从来就没想过会有这样的\n一天？能够独当一面，建立超越丞相的\n功业。\n&姜维\n我虽然有想过…但不希望是以这样的形式\n取得权力。\n&柳隐\n你还在怕世人的指责？怕暗杀大将军的\n污名找上你？\n&柳隐\n丞相过去面对欺压幼主的污名时，他有\n说过一句话？他用行动堵住那些人的嘴。\n&柳隐\n老大你也应该这样，只要完成丞相托付\n的使命，旁边的人怎么说又如何？\n&姜维\n你知道丞相和司马懿差在哪里？两人虽都\n是权倾一时的大臣，但丞相知道克制自己\n，不使用暴力夺取政权。\n&姜维\n对比之下，司马懿选择用屠刀将政敌铲除\n，两人高下立分。\n&姜维\n我大汉自从魏文长之事后，内部就再也\n没有发生过流血冲突，这不能不归功于\n丞相的自制。\n&姜维\n今日如果我效法司马懿，用暴力铲除大\n将军，明日也会有人效法我，用暴力将\n我铲除。\n&姜维\n如此暴力相向，以血洗血，大汉江山\n经不起这样的折腾。\n&柳隐\n我也明白这道理，但用相忍让的方式来\n政权交替，只会变成无能官僚的温床。\n&姜维\n休然，过去的我或许也会有你这样的\n想法。\n&姜维\n但现在我逐渐认为，与其让有能的暴虐者\n上台施暴，还不如让平庸的官僚继续做下\n去。\n&柳隐\n………\n&柳隐\n（老大的思想很了不起，不过如果他不\n上台，就没有实践的可能性。）\n&柳隐\n（谯周等人根本就搞不清楚状况，老大\n才是我们益州人获得解放的希望。）"]},{"op":"actor_face","args":[3,0,2]},{"op":"delay","args":[5]},{"op":"actor_face","args":[22,6,3]},{"op":"dialog","args":["&张嶷\n不管真相如何，只要伯约继续为大汉尽忠\n，我张嶷就会力挺到底。\n&张嶷\n不过眼前有另外一件事情想要请诸葛姑娘\n帮忙转达。"]},{"op":"actor_face","args":[1,6,1]},{"op":"dialog","args":["&诸葛果\n关于从兄的事情？\n&张嶷\n我还没说出口，你就知道我在想什么，\n实在是令人赞叹。\n&张嶷\n诸葛恪要北伐的事情已经传遍大江南北，\n或许不久以后要求我们共同发兵的通知也\n会过来。\n&张嶷\n但是诸葛恪却不知道，他那样的举动已经\n要大祸临头。\n&张嶷\n东吴政治生态和大汉完全不同，经过孙权\n执政末期的动荡，已经无法确保大规模军\n事行动后的安定。\n&张嶷\n我也听闻孙权生杀赏罚，权柄紧握在自己\n手上，不交给别人。直到死前才徵召诸葛\n恪，这决定未必经过深思熟虑。\n&张嶷\n吴楚地区的人又生性冲动，诸葛恪远离\n幼主，深入敌人国土，只会给他的政敌\n制造难得的机会。\n&诸葛果\n果在十天前就已经写信给从兄，希望他\n能再三思，不过没有获得回信。\n&张嶷\n这样…那诸葛恪真是要大祸临头了。"]},{"op":"delay","args":[5]},{"op":"actor_face","args":[22,0,0]},{"op":"actor_face","args":[1,0,3]},{"op":"dialog","args":["&诸葛果\n主公，现在唯一可以做的事情，只有配合\n诸葛恪的军事行动，同时发动攻击。\n&诸葛果\n虽说诸葛恪那边胜算不高，但是至少可以\n确定牵制住敌人大部分的军队。\n&杨兰\n（又来了，明明心中对于自己从兄即将要\n死亡感到悲伤，却又不肯说出口。）\n&杨兰\n（刚开始会觉得这女人很厉害，现在久了\n大概也知道她不过是个爱逞强的普通女人\n而已。）\n&姜维\n嗯…我也有这样的打算，两面夹击贼军，\n一定可以给贼军很大的压力。\n&姜维\n现在正是进军陇西，实现我规划已久战略\n的时刻。"]},{"op":"delay","args":[5]},{"op":"actor_action","args":[0,17]},{"op":"dialog","args":["&姜维\n我会禀明圣上，请求从汉中向武都出发，\n沿著石营向南安进兵。\n&姜维\n只要能够拿下南安，就可以彻底切断贼军\n向狄道出兵的通路。\n&姜维\n再者，南安到狄道的通路地形狭窄，陇西\n驻军要攻过来也会遇到阻碍。\n&姜维\n这时，我们可以视情况和贼军进行野战，\n只要战胜，就可以取得陇西的支配权。"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[62]},{"op":"change_scene","args":[2,65535,65535,51,65535]},{"op":"actor_appear","args":[68,51,29,2,0]},{"op":"actor_appear","args":[71,41,52,1,0]},{"op":"actor_appear","args":[578,41,57,1,0]},{"op":"actor_appear","args":[551,41,62,1,0]},{"op":"actor_appear","args":[579,41,67,1,0]},{"op":"actor_appear","args":[672,41,72,1,0]},{"op":"actor_appear","args":[94,51,49,0,0]},{"op":"actor_appear","args":[99,65,52,3,0]},{"op":"actor_appear","args":[130,65,57,3,0]},{"op":"actor_appear","args":[580,65,62,3,0]},{"op":"actor_appear","args":[589,65,67,3,0]},{"op":"actor_appear","args":[107,65,72,3,0]},{"op":"fade_out","args":[]},{"op":"place_name","args":["洛阳宫殿"]},{"op":"title_text","args":["子元之担当"]},{"op":"actor_face","args":[94,0,2]},{"op":"dialog","args":["&许允\n大将军这次出兵可真是战果丰硕，数万的\n死者，又损失了前部督韩综。\n&张缉\n莫非大将军知道孙权刚死，想要送上韩综\n的脑袋献祭？哈哈哈…\n&王肃\n这次的作战全是诸葛诞提供的，要怪应该\n怪诸葛诞，怎么可以怪到大将军头上？"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&夏侯玄\n不，我认为发动这场没有计画的攻击，\n只想成就己之利，就是大将军的过失。\n&王肃\n这……\n&傅嘏\n确实太常说得也很有道理。\n&司马孚\n大将军是不是应该也有所表示？"]},{"op":"actor_action","args":[94,6]},{"op":"dialog","args":["&司马师\n没错，这次全是我的过失才造成这样的惨\n败，只是这次作战是因为没有采纳公休的\n意见才惨败，怎么可以处罚公休？\n&司马师\n（这个夏侯太初变得这么可怕，只说一\n句话就能让整个舆论风向转变。）\n&司马师\n（之后有机会我一定要干掉你！）\n&夏侯玄\n那么总得有人为这次的败战负责。"]},{"op":"actor_action","args":[130,6]},{"op":"dialog","args":["&司马昭\n就处罚我吧！我担任监军不力，甘愿领罚\n以正军纪。\n&司马师\n（真是我的好弟弟。）\n&司马师\n那么就剥夺司马昭的爵位，以告慰阵亡\n将士的灵魂。\n&司马昭\n遵命！"]},{"op":"actor_action","args":[130,0]},{"op":"actor_action","args":[94,0]},{"op":"actor_face","args":[71,6,0]},{"op":"dialog","args":["&夏侯玄\n陛下，正始年间臣曾与太傅一同提倡应\n当以孝治天下。 现在大将军也标榜此事\n，克绍箕裘，孝顺之名果不虚假。\n&夏侯玄\n这次大战，至少有数万人下落不明，\n甚至遗体被丢在敌境。\n&夏侯玄\n照清议，孝子安葬父母并服丧后才能\n成婚、仕宦。\n&夏侯玄\n现在这数万家庭的孝子都无法安葬父兄\n，难道在大将军从吴贼手中抢回遗体前\n，他们要无限期地绝婚宦？"]},{"op":"actor_face","args":[94,0,3]},{"op":"dialog","args":["&司马师\n（太初你这家伙在恶整我吗？我去哪找回\n那数万的尸体？）\n&司马师\n（要是禁绝婚宦，我八成会被暴动搞垮。\n但是不禁婚宦，我就违背孝治天下的口号\n，你回到洛阳真的不是来夺权？）"]},{"op":"actor_face","args":[94,6,0]},{"op":"dialog","args":["&司马师\n圣人说过“发乎情，止乎礼”，所以礼法\n不外乎人情。\n&司马师\n孟子也说“食、色，性也”，长期禁止\n成婚、仕宦的确不妥。\n&司马师\n我们应该因缘制礼,制定符合时代特色的\n礼制。由陛下下诏，特准家属发丧，并在\n服丧结束后恢复成婚、仕宦的权力。\n&曹芳\n既然大将军有这样的想法，朕也会从善\n如流。"]},{"op":"actor_face","args":[71,0,1]},{"op":"dialog","args":["&夏侯玄\n（真会掰，“发乎情，止乎礼”\n哪是这意思？本领没长多少倒是\n口才变好了。）\n&夏侯玄\n（不过经历这次教训，相信司马师应该会\n收敛点。）\n&张缉\n（这什么态度？打败仗还用这种口气\n要我女婿下诏帮你擦屁股。有机会一定\n要你好看。）"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&高柔\n那些事情可以之后再议。\n&高柔\n现在吴逆率领二十万大军入侵，而同时\n蜀贼也开始入侵凉州，两面夹击，我们\n可陷入空前的危机。"]},{"op":"actor_face","args":[94,0,2]},{"op":"dialog","args":["&张缉\n先不用担心吴逆那边，诸葛恪不久将会\n死于非命。\n&司马师\n为什么？\n&张缉\n威震君主，功盖全国，如何能不死？\n&司马师\n（你这家伙，表面上说诸葛恪，实际上\n在说我，我又怎么会不知道。）"]},{"op":"play_sound","args":[50]},{"op":"actor_face","args":[107,6,0]},{"op":"dialog","args":["&钟会\n这样的说法根本就无助于解决问题。\n&司马师\n确实如此，东西两地都受到攻击，将领们\n可是意志消沉。\n&钟会\n诸葛恪率领全部精锐，足可以横冲直撞\n，给我们很大伤害，想不到却集中力量\n，围困一个据点。\n&钟会\n他的用意在吸引我们野战军主力决战。\n然而如果攻城不破，会战不可得，战斗力\n衰退，他就只有撤退一途。\n&钟会\n姜维大军深入，必定认为我们正在东方\n有事，西方空虚，如果命关中将领率军\n支援，出其不意，姜维必定退兵。"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&司马师\n好！这就命郭淮和陈泰迎击姜维。\n&司马师\n至于对付吴逆的人选，我认为毌丘俭有勇\n有谋，加上上次战争诸葛诞部队损失惨重\n，所以让这两人互换。\n&司马师\n（藉著这个机会，把公休调到距离我较近\n的荆豫地带，让他和文舒合作巩固好荆州\n防线。）\n&司马师\n（至于毌丘俭，就让他和吴逆打得你死\n我活，削弱他的实力吧…这个心腹大患\n，早晚要除掉。）"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[22]},{"op":"change_scene","args":[2,65535,65535,18,65535]},{"op":"actor_appear","args":[80,34,54,1,0]},{"op":"actor_appear","args":[112,48,43,2,0]},{"op":"actor_appear","args":[118,53,43,2,0]},{"op":"actor_appear","args":[116,48,69,0,0]},{"op":"actor_appear","args":[56,53,69,0,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["郭淮的意志"]},{"op":"place_name","args":["洛门 魏军营帐"]},{"op":"dialog","args":["&郭淮\n姜维居然想到出兵南安…万一真的被他\n攻下来，南安以西的州郡都有危险。\n&郭淮\n现在即刻率领全军前往救援，一刻也不能\n再等下去。"]},{"op":"actor_face","args":[112,6,3]},{"op":"dialog","args":["&陈泰\n在下认为车骑将军您这次的行动太轻率，\n其实只要固守要地就足以让姜维退兵，没\n有必要和他交战，这样只会正中他下怀。\n&郭淮\n本来应该是这样…但这次姜维出动的军队\n数量非同小可，费祎的死亡让蜀地已经没\n有牵制他的力量。\n&郭淮\n以陇西部队现有战力和姜维军团对阵，\n绝对没有任何胜算。\n&郭淮\n反而如果现在以我关中部队和姜维进行\n野战，获胜机会还有一半。\n&郭淮\n但如果姜维取得有利地形，切断陇西部队\n和我们关中部队的联系，到时要获胜就难\n了。\n&陈泰\n我明白了…\n&陈泰\n（伯济的妻子是王凌的妹妹，虽然因为\n伯济的求情而被放过一马，但是他现在\n心中的压力一定大得不得了。）\n&陈泰\n（他想要早日立功还司马家那个人情，但\n现在看来只是让伯济越来越失去冷静。）\n&郭淮\n玄伯也看出我很急？\n&陈泰\n看来在下隐藏表情的工夫还是太嫩了。\n&郭淮\n和内人的事情无关，这是我第一次和伯约\n以相同军力对决，我并没有必胜的把握。\n&郭淮\n所以我这次要出狠招，不知道玄伯愿意\n配合吗？\n&陈泰\n非常乐意。\n&郭淮\n那么就让玄伯率领先遣部队在铁笼山附近\n迎击姜维，句安和王韬两位就随你一同前\n往。"]},{"op":"actor_face","args":[56,6,3]},{"op":"actor_face","args":[118,0,3]},{"op":"dialog","args":["&王韬\n是！\n&句安\n是！\n（干！又是这种吃力不讨好的工作。）"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&郭淮\n如果没有什么意外，玄伯你会被打得很惨\n，甚至被困在山上。\n&陈泰\n难道车骑将军这么看轻我？\n&郭淮\n不，我希望你被那样困住。\n&郭淮\n伯约这次出兵为了增加胜算，所以特别请\n羌人助阵，但这却制造了他的弱点。\n&陈泰\n是说要策反那些羌人？\n&郭淮\n我听说迷当和姚柯回已经应了姜维的要求\n出兵，不过这点请玄伯放心，我有应付之\n道。\n&陈泰\n我已经完全明白车骑将军的战术，请将军\n放心，我会扮演好自己的角色。\n&郭淮\n被包围的过程很辛苦，但是请玄伯你一定\n要撑下去。\n&郭淮\n徐护军！即刻联络姚柯回，就说这次是个\n好机会…"]},{"op":"actor_face","args":[116,6,3]},{"op":"dialog","args":["&徐质\n机会？\n&郭淮\n这个姚柯回就像个饿狼一样，哪里有肉就\n往哪边去。\n&郭淮\n只是姜维没想过，那个饿狼要的东西是\n他给不起的。"]},{"op":"choice","args":["合兵一处\n分兵包围",80]},{"op":"if","cond":"always","args":[],"end":30},{"op":"if","cond":"test_choice","args":[1],"end":24},{"op":"dialog","args":["&郭淮\n在援军到达后就和我合兵一处，毕竟兵力\n不足的包围网反而效果不彰。"]},{"op":"endif","args":[]},{"op":"if","cond":"test_choice","args":[2],"end":28},{"op":"dialog","args":["&郭淮\n徐护军，到时候请你配合羌人部队，从\n铁笼山西方包夹。\n&郭淮\n只要包围网确立，姜维插翅难飞。\n&陈泰\n（郭将军施计时光芒万丈，但为什么我会\n感觉有些不安呢？）"]},{"op":"set_flag","args":[1021,1]},{"op":"endif","args":[]},{"op":"actor_face","args":[1,0,0]},{"op":"endif","args":[]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[0]},{"op":"change_scene","args":[2,65535,65535,20,65535]},{"op":"actor_appear","args":[582,75,55,3,0]},{"op":"actor_appear","args":[217,60,54,1,0]},{"op":"fade_out","args":[]},{"op":"place_name","args":["羌王营帐"]},{"op":"actor_action","args":[217,6]},{"op":"dialog","args":["&王嗣\n这些是我大汉致赠您的金银珠宝，也请您\n笑纳。\n&姚柯回\n这次一起出兵的还有谁？\n&王嗣\n还有迷当大王。\n&姚柯回\n原来如此…好，本王愿意出兵。\n&姚柯回\n关于五年前的事情也请不要见怪，毕竟那\n时候受到郭淮压迫，没办法才做出那样的\n事情。\n&王嗣\n我明白，这些我都会禀报卫将军的。"]},{"op":"actor_action","args":[217,0]},{"op":"dialog","args":["&王嗣\n（我和那么多羌人接触过，就是这个人让\n我完全无法捉摸，究竟他会不会如约帮我\n们，其实我都没有把握。）\n&王嗣\n（唉…要是这次害了伯约，恐怕我会内咎\n一辈子吧。）"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[25]},{"op":"change_scene","args":[2,65535,65535,18,65535]},{"op":"actor_appear","args":[0,35,54,1,0]},{"op":"actor_appear","args":[9,46,45,2,0]},{"op":"actor_appear","args":[4,51,45,2,0]},{"op":"actor_appear","args":[3,56,45,2,0]},{"op":"actor_appear","args":[2,61,45,2,0]},{"op":"actor_appear","args":[16,66,45,2,0]},{"op":"actor_appear","args":[12,46,66,0,0]},{"op":"actor_appear","args":[22,51,66,0,0]},{"op":"actor_appear","args":[1,56,66,0,0]},{"op":"actor_appear","args":[5,61,66,0,0]},{"op":"actor_appear","args":[20,66,66,0,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["郭淮的终战"]},{"op":"place_name","args":["姜维军营帐"]},{"op":"dialog","args":["&姜维\n如同之前所说的，我军这次目标是南安，\n并且伺机寻求和敌人野战的机会。\n&姜维\n我军军队人数充足，应该可以避免过去\n因为人数不足而无法进行决战的困境。\n&姜维\n另外我也请承宗前往西羌联络了迷当和\n姚柯回作为援军。"]},{"op":"delay","args":[5]},{"op":"actor_face","args":[2,3,3]},{"op":"dialog","args":["&杨兰\n为什么这么重要的事情不和我说？\n&姜维\n我只是想因为你也要负责出征的事宜，\n所以联络羌人的工作改叫承宗负责。\n&杨兰\n（我知道你是因为上次治无戴的事情怕我\n难过，但是现在这情况我还是要说…）\n&杨兰\n迷当是个胆小鬼先不论，姚柯回那个完全\n不讲信用的家伙怎么能相信？\n&姜维\n可目前羌人势力最庞大的就是姚柯回部\n，至少不能让他成为曹贼的盟友。\n&杨兰\n姚柯回不能信任，上次治无戴就是因为\n相信他才落得被袭击的命运，为什么就\n是学不到教训？\n&张嶷\n杨姑娘冷静点，我想如果姚柯回不叛变\n的话，这次作战应该是十拿九稳。\n&张嶷\n过去也很多人说南中人不讲信用，叛服\n无定，但现在我军中南中部队也占有相\n当比例。\n&张嶷\n我想只要掌握到姚柯回心中真正想要的\n东西就可以收服他。\n&杨兰\n这……\n&杨兰\n（我很难想像有什么是他真心想要的。）"]},{"op":"actor_face","args":[2,0,2]},{"op":"actor_face","args":[3,6,3]},{"op":"dialog","args":["&柳隐\n敌人前锋似乎是陈泰，没有看见郭淮的\n影子。\n&姜维\n如果分两部分行军的话，个别击破本来\n应该会是最好方式。\n&柳隐\n不过…老大，这计画实际上实行起来，\n恐怕没那么容易吧…陈泰并非庸才。\n&姜维\n不知各位有什么想法呢？"]},{"op":"delay","args":[5]},{"op":"actor_face","args":[1,0,3]},{"op":"dialog","args":["&诸葛果\n主公，南安附近有座山名为铁笼山，或许\n可以派上用场。\n&姜维\n对！就是这个…我们不妨就用铁笼山来\n制造个现成的监狱。\n&句扶\n现成的监狱？\n&姜维\n利用铁笼山就可以避免陈泰的部队逃窜，\n可以彻底歼灭陈泰的军队，这样就能完成\n各个击破的战术。\n&姜维\n（只是伯济为什么要分兵？明知道分兵对\n自己只有害无利，他到底在打什么主意，\n实在是很让人在意。）"]},{"op":"actor_face","args":[3,0,2]},{"op":"actor_face","args":[1,0,0]},{"op":"play_sound","args":[21]},{"op":"battle_select_units","args":[1,14,65535,65535,1,2,0,65535,65535,65535,65535,65535]},{"op":"battle_select_units","args":[1,14,65535,65535,65535,65535,65535,65535,65535,65535,65535,65535]},{"op":"battle_select_units","args":[1,14,65535,65535,65535,65535,65535,65535,65535,65535,65535,65535]},{"op":"endif","args":[]},{"op":"actor_action","args":[0,17]},{"op":"dialog","args":["&姜维\n出发。"]},{"op":"battle_select_units","args":[0,0,65535,65535,65535,65535,65535,65535,65535,65535,65535,65535]},{"op":"fade_in","args":[]},{"op":"play_sound","args":[255]},{"op":"endif","args":[]},{"op":"dialog","args":["&姜维\n嗯…元逊不是个笨蛋，我想他应该会平安\n无事的。\n&诸葛果\n主公请不要为我担心，像我这种微贱的存\n在是不需要您特别挂念的。\n&姜维\n（总觉得就像丞相过世时那样，她似乎在\n逞强。）"]},{"op":"endif","args":[]},{"op":"dialog","args":["&姜维\n我并不恨你，但是有件事情还是要请你\n知道，不要把所有的罪孽都揽到自己身\n上来。\n&姜维\n如果你要下十八层地狱的话，至少让我帮\n你分担一层吧。\n&宁随\n伯约……\n&宁随\n（冲著你这句话，就算下十八层地狱又如\n何？）"]},{"op":"endif","args":[]},{"op":"dialog","args":["&杨兰\n我还是想说，不要信任姚柯回那个家伙。\n&姜维\n（这个姚柯回有这么不值得信任？）"]},{"op":"endif","args":[]},{"op":"dialog","args":["&花鬘\n我倒认为比起我们南中人或是羌人，汉人\n才是最不讲信用的啦。"]},{"op":"endif","args":[]},{"op":"dialog","args":["&袁綝\n司马家的人面临这样两面包夹的局面，\n不知道想出什么应对的手段。\n&袁綝\n司马懿这一死究竟影响会有多大，我还真\n是想看看司马懿儿子们的实力。"]},{"op":"endif","args":[]},{"op":"dialog","args":["&关索\n传闻东吴打赢东兴之战，是因为有个可爱\n的女将在前面奋勇杀敌。\n&关索\n呵呵呵…好想见她一面…\n&花鬘\n关索，这次你是想要去乌戈国玩一趟吗？"]},{"op":"endif","args":[]},{"op":"dialog","args":["&姜维\n没想到德艳也会加入我们的行列。\n&宗预\n毕竟这是伯苗最后的遗愿，而我本身也想\n上前线为我大汉尽一份力。\n&姜维\n原来如此，还是请你多指教。"]},{"op":"endif","args":[]},{"op":"dialog","args":["&张嶷\n唉…我的预言接二连三命中，实在一点也\n高兴不起来。\n&张嶷\n希望诸葛恪能够逃过一劫。"]},{"op":"endif","args":[]},{"op":"dialog","args":["&句扶\n这次一定要斩下句安的脑袋，我不会再有\n犹豫了。\n&姜维\n孝兴，千万不要勉强。\n&句扶\n这是为了大汉，并不是出于私怨，请统帅\n你放心。"]},{"op":"endif","args":[]},{"op":"dialog","args":["&柳隐\n老大，有件事情我想你应该很明白。\n&柳隐\n如果不是费祎当年的阻挠，在北伐最有\n可能成功的时候阻止出兵，现在我们可\n能已经在长安了。\n&柳隐\n机会一去实在很难复返，为了避免以后\n再发生这样的困扰，我建议你应该要思\n考控制朝廷的方法。\n&姜维\n休然，这一点你已经不需要担心了，\n新上任的尚书令答应给我们全面支援。\n&柳隐\n真的？"]},{"op":"endif","args":[]},{"op":"enter_battle","args":[]}]},"battles":[{"src":"S_20"}]});
})();
